(function () {
  'use strict';
  var FILES = [{"name":"demo/aflow.css","mime":"text/css","data":"/* =========================================================\n   AFlow · 算法解剖引擎样式\n   浅色主题，配色与主站令牌一致。三个案例包共用同一份。\n   ========================================================= */\n.af {\n  --af-ink: #242b2e; --af-ink2: #4d565b; --af-ink3: #79828a; --af-ink4: #9ba3a9;\n  --af-line: #e9e4d8; --af-line2: #f0ece1;\n  --af-jade: #2f7d6b; --af-jade-l: #e6f1ec; --af-jade-d: #22604f;\n  --af-clay: #b26a39; --af-red: #b05a51; --af-blue: #41699b;\n  border: 1px solid var(--af-line); border-radius: 12px; background: #fff;\n  padding: 14px 16px 12px; margin-top: 12px;\n}\n\n/* ---- 顶栏 ---- */\n.af-top { display: flex; align-items: center; justify-content: space-between; gap: 14px; flex-wrap: wrap; }\n.af-head { min-width: 0; }\n.af-ttl {\n  display: inline-block; font-size: 10px; font-weight: 700; letter-spacing: .1em;\n  color: var(--af-jade); font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  background: var(--af-jade-l); border-radius: 4px; padding: 2px 8px; margin-right: 8px;\n}\n.af-sub { font-size: 12.5px; color: var(--af-ink2); }\n.af-ctrls { display: flex; align-items: center; gap: 4px; flex-shrink: 0; }\n.af-b {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  width: 28px; height: 26px; border-radius: 6px; cursor: pointer;\n  font-size: 12px; line-height: 1; font-family: inherit;\n  display: inline-flex; align-items: center; justify-content: center;\n  transition: all .14s;\n}\n.af-b:hover { border-color: var(--af-jade); color: var(--af-jade-d); background: var(--af-jade-l); }\n.af-play { width: 34px; font-size: 10px; }\n.af-sp {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  border-radius: 6px; height: 26px; font-size: 11px; font-family: inherit; padding: 0 4px; cursor: pointer;\n}\n.af-sp:focus { outline: 2px solid var(--af-jade); outline-offset: 1px; }\n\n/* ---- 阶段轨道 ---- */\n.af-rail {\n  display: flex; gap: 4px; margin-top: 11px; overflow-x: auto; padding-bottom: 2px;\n  scrollbar-width: thin;\n}\n.af-node {\n  flex: 1 1 0; min-width: 96px; text-align: left; cursor: pointer; font-family: inherit;\n  border: 1px solid var(--af-line); background: #fff; border-radius: 7px;\n  padding: 5px 8px 6px; display: block; transition: all .16s; position: relative;\n}\n.af-node:hover { border-color: var(--af-jade); }\n.af-node .af-n {\n  display: inline-block; font-size: 9px; font-weight: 700; color: var(--af-ink4);\n  font-family: ui-monospace, monospace; margin-right: 5px;\n}\n.af-node .af-nm { font-size: 11.5px; color: var(--af-ink2); font-weight: 600; }\n.af-node .af-tg {\n  display: block; font-size: 9px; color: var(--af-ink4); margin-top: 1px;\n  font-family: ui-monospace, monospace; letter-spacing: .01em;\n}\n.af-node.done { border-color: #cfe3da; background: #f7fbf9; }\n.af-node.done .af-n { color: var(--af-jade); }\n.af-node.on { border-color: var(--af-jade); background: var(--af-jade-l); box-shadow: 0 0 0 2px rgba(47,125,107,.1); }\n.af-node.on .af-n { color: var(--af-jade-d); }\n.af-node.on .af-nm { color: var(--af-jade-d); }\n.af-node.on .af-tg { color: var(--af-jade); }\n\n/* ---- 进度条 ---- */\n.af-prog { height: 3px; background: var(--af-line2); border-radius: 2px; margin-top: 8px; overflow: hidden; }\n.af-prog i { display: block; height: 100%; background: var(--af-jade); border-radius: 2px; transition: width .06s linear; }\n\n/* ---- 舞台 ---- */\n.af-stage { margin-top: 10px; }\n.af-stage svg {\n  display: block; width: 100%; height: auto; max-height: 620px;\n  background: #fbfaf6; border: 1px solid var(--af-line); border-radius: 9px;\n}\n\n/* ---- 说明 + 读数 ---- */\n.af-meta { display: grid; grid-template-columns: 1fr 250px; gap: 12px; margin-top: 10px; align-items: start; }\n.af-note {\n  font-size: 12.5px; line-height: 1.72; color: var(--af-ink2);\n  background: #f4f3ef; border-left: 3px solid var(--af-jade); border-radius: 0 5px 5px 0;\n  padding: 8px 12px; min-height: 38px;\n}\n.af-note b { color: var(--af-ink); font-weight: 700; }\n.af-note code, .af-note .mono {\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 11.5px;\n  background: #fff; border: 1px solid var(--af-line); border-radius: 3px; padding: 0 4px;\n}\n.af-stats { display: flex; flex-wrap: wrap; gap: 5px; align-content: flex-start; }\n.af-stat {\n  background: #fff; border: 1px solid var(--af-line); border-radius: 6px;\n  padding: 4px 9px; min-width: 74px; flex: 1 1 auto;\n}\n.af-stat .k { display: block; font-size: 9.5px; color: var(--af-ink4); letter-spacing: .02em; }\n.af-stat .v {\n  display: block; font-family: ui-monospace, monospace; font-size: 13px;\n  font-weight: 600; color: var(--af-ink); margin-top: 1px;\n}\n.af-stat.t-ok .v { color: var(--af-jade-d); }\n.af-stat.t-warn .v { color: var(--af-clay); }\n.af-stat.t-bad .v { color: var(--af-red); }\n\n.af-count { margin-top: 7px; font-size: 10.5px; color: var(--af-ink4); font-family: ui-monospace, monospace; text-align: right; }\n\n@media (max-width: 860px) {\n  .af-meta { grid-template-columns: 1fr; }\n  .af-node { min-width: 84px; }\n  .af-node .af-nm { font-size: 11px; }\n}\n"},{"name":"demo/aflow.js","mime":"text/javascript","data":"/* =========================================================\n   AFlow · 算法解剖引擎（纯前端，零依赖）\n   ---------------------------------------------------------\n   用途：把「模型算法从输入走到输出」拆成若干可播放的阶段。\n   每个阶段跑的是真实的一段中间计算（不是抽象节点示意），\n   引擎负责：阶段轨道 / 播放控制 / 进度 / 实时读数 / 说明文字。\n\n   两种阶段写法\n   ------------\n   A) SVG 阶段 —— 适合示意图型中间量\n      { name, tag, dur,\n        draw: function (t, g, ctx) {\n          return { svg: '...', stats: [{k,v,tone}], note: '...' };\n        } }\n\n   B) DOM 阶段 —— 适合逐像素 / 逐节点的真实计算动画\n      { name, tag, dur,\n        init: function (host) {          // 只跑一次，构建 DOM\n          return {\n            update: function (t, ctx) {  // 每帧调用，负责重绘\n              return { stats: [...], note: '...' };\n            }\n          };\n        } }\n\n   用法：\n     AFlow.create({\n       mount: document.getElementById('flowMount'),\n       state: {},\n       stages: [ ... ]\n     });\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* ---------------- 配色（浅色主题，与主站令牌一致） ---------------- */\n  var C = {\n    ink: '#242b2e', ink2: '#4d565b', ink3: '#79828a', ink4: '#9ba3a9',\n    line: '#e9e4d8', line2: '#f0ece1', paper: '#fbfaf6', card: '#ffffff',\n    jade: '#2f7d6b', jadeL: '#e6f1ec', jadeD: '#22604f',\n    clay: '#b26a39', clayL: '#f8ecdf',\n    blue: '#41699b', blueL: '#e7eef9',\n    purple: '#7e5a8d', purpleL: '#efe9f4',\n    amber: '#c98a2b', amberL: '#faf3e2',\n    red: '#b05a51', redL: '#f9e9e5',\n    gray: '#79828a', grayL: '#f1f1ee'\n  };\n\n  /* 三栏坐标系：输入 → 算法内部 → 输出。画布 1000×520 */\n  var COLS = [\n    { x: 18, w: 272 },\n    { x: 312, w: 372 },\n    { x: 706, w: 276 }\n  ];\n  var TOP = 30, PANEL_H = 440, RAIL_Y = 484;\n\n  /* ---------------- 绘图 helper ---------------- */\n  var G = {\n    C: C, COLS: COLS, TOP: TOP, PANEL_H: PANEL_H,\n\n    esc: function (s) {\n      return String(s == null ? '' : s)\n        .replace(/&/g, '&amp;').replace(/<\/g, '&lt;').replace(/>/g, '&gt;');\n    },\n    f: function (v, n) {\n      n = (n === undefined) ? 2 : n;\n      if (v === null || v === undefined || !isFinite(v)) return '—';\n      return Number(v).toFixed(n);\n    },\n    rect: function (x, y, w, h, o) {\n      o = o || {};\n      return '<rect x=\"' + x + '\" y=\"' + y + '\" width=\"' + Math.max(0, w) + '\" height=\"' + Math.max(0, h) +\n        '\" rx=\"' + (o.r == null ? 4 : o.r) + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') + '/>';\n    },\n    line: function (x1, y1, x2, y2, o) {\n      o = o || {};\n      return '<line x1=\"' + x1 + '\" y1=\"' + y1 + '\" x2=\"' + x2 + '\" y2=\"' + y2 +\n        '\" stroke=\"' + (o.stroke || C.line) + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') + '/>';\n    },\n    path: function (d, o) {\n      o = o || {};\n      return '<path d=\"' + d + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.5 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') +\n        (o.join ? ' stroke-linejoin=\"' + o.join + '\"' : '') + '/>';\n    },\n    txt: function (x, y, s, o) {\n      o = o || {};\n      var size = o.size == null ? 11 : o.size;\n      var fill = o.fill || C.ink2;\n      var anchor = o.anchor || 'start';\n      var weight = o.weight ? ' font-weight=\"' + o.weight + '\"' : '';\n      var fam = o.mono ? ' font-family=\"ui-monospace,SFMono-Regular,Menlo,Consolas,monospace\"' : '';\n      var extra = (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.ls ? ' letter-spacing=\"' + o.ls + '\"' : '');\n      return '<text x=\"' + x + '\" y=\"' + y + '\" text-anchor=\"' + anchor + '\" font-size=\"' + size +\n        '\" fill=\"' + fill + '\"' + weight + fam + extra + '>' + G.esc(s) + '<\/text>';\n    },\n    circle: function (cx, cy, r, o) {\n      o = o || {};\n      return '<circle cx=\"' + cx + '\" cy=\"' + cy + '\" r=\"' + r + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.2 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') + '/>';\n    },\n    poly: function (pts, o) {\n      o = o || {};\n      var d = '';\n      for (var i = 0; i < pts.length; i++) d += (i ? 'L' : 'M') + pts[i][0].toFixed(1) + ' ' + pts[i][1].toFixed(1) + ' ';\n      return G.path(d + (o.close ? 'Z' : ''), o);\n    },\n    /* 标准三栏面板：全站统一的「输入 / 算法内部 / 输出」视觉语法 */\n    panel: function (ci, title, sub, color, dim) {\n      var c = COLS[ci];\n      var o = G.rect(c.x, TOP, c.w, PANEL_H, {\n        r: 8, fill: '#ffffff', stroke: dim ? '#efece1' : C.line, sw: 1\n      });\n      o += G.rect(c.x, TOP, c.w, 3, { r: 1.5, fill: color || C.line, op: dim ? 0.32 : 1 });\n      o += G.txt(c.x + 13, TOP + 25, title, { size: 12.5, fill: dim ? C.ink3 : C.ink, weight: 700 });\n      if (sub) o += G.txt(c.x + 13, TOP + 41, sub, { size: 10, fill: C.ink4 });\n      o += G.line(c.x, TOP + 50, c.x + c.w, TOP + 50, { stroke: C.line2 });\n      return o;\n    },\n    /* 栏间箭头：标出「数据流向下一层」 */\n    arrow: function (x, y, color, label, sub) {\n      var o = G.path('M' + x + ' ' + (y - 5) + 'L' + (x + 11) + ' ' + y + 'L' + x + ' ' + (y + 5) +\n        'L' + (x + 3) + ' ' + y + 'Z', { fill: color || C.line });\n      if (label) o += G.txt(x - 2, y - 11, label, { size: 9.5, fill: color || C.ink3, anchor: 'middle', weight: 700 });\n      if (sub) o += G.txt(x - 2, y + 18, sub, { size: 8.5, fill: C.ink4, anchor: 'middle' });\n      return o;\n    },\n    /* 数据形态缎带：把「输入张量 → 中间张量 → 输出张量」的形状串成一条 */\n    shapes: function (list, active) {\n      if (!list || !list.length) return '';\n      var o = '', x = 18, w = 964;\n      var n = list.length, pad = 7;\n      var cw = (w - pad * (n - 1)) / n;\n      for (var i = 0; i < n; i++) {\n        var on = (i === active);\n        o += G.rect(x, RAIL_Y, cw, 24, {\n          r: 5, fill: on ? C.jadeL : '#ffffff', stroke: on ? C.jade : C.line, sw: on ? 1.3 : 1\n        });\n        o += G.txt(x + cw / 2, RAIL_Y + 16, list[i], {\n          size: 9.5, anchor: 'middle', mono: true,\n          fill: on ? C.jadeD : C.ink3, weight: on ? 700 : 400\n        });\n        if (i < n - 1) o += G.txt(x + cw + pad / 2, RAIL_Y + 16, '→', { size: 10, fill: C.ink4, anchor: 'middle' });\n        x += cw + pad;\n      }\n      return o;\n    },\n    axes: function (x, y, w, h, o) {\n      o = o || {};\n      var s = G.rect(x, y, w, h, { r: 4, fill: o.fill || '#fdfdfb', stroke: o.stroke || C.line2 });\n      if (o.nx) for (var i = 1; i < o.nx; i++) {\n        s += G.line(x + w * i / o.nx, y, x + w * i / o.nx, y + h, { stroke: C.line2, op: 0.7 });\n      }\n      if (o.ny) for (var j = 1; j < o.ny; j++) {\n        s += G.line(x, y + h * j / o.ny, x + w, y + h * j / o.ny, { stroke: C.line2, op: 0.7 });\n      }\n      return s;\n    }\n  };\n\n  /* ---------------- 引擎 ---------------- */\n  function create(opts) {\n    var mount = opts.mount;\n    if (!mount) return null;\n    var stages = (opts.stages || []).filter(function (s) { return s && (typeof s.draw === 'function' || typeof s.init === 'function'); });\n    if (!stages.length) return null;\n\n    var state = opts.state || {};\n    var idx = 0, t = 0, playing = opts.autoplay !== false, speed = 1;\n    var raf = null, lastTs = 0, dirty = true;\n    var domStage = null, domHandle = null;\n\n    mount.innerHTML =\n      '<div class=\"af\">' +\n      '  <div class=\"af-top\">' +\n      '    <div class=\"af-head\">' +\n      '      <span class=\"af-ttl\">' + G.esc(opts.title || '算法解剖') + '<\/span>' +\n      '      <span class=\"af-sub\">' + G.esc(opts.subtitle || '自动播放：输入怎么一步步变成输出') + '<\/span>' +\n      '    <\/div>' +\n      '    <div class=\"af-ctrls\">' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"prev\" title=\"上一步\">‹<\/button>' +\n      '      <button type=\"button\" class=\"af-b af-play\" data-a=\"play\" title=\"播放/暂停\">❚❚<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"next\" title=\"下一步\">›<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"reset\" title=\"重播\">↺<\/button>' +\n      '      <select class=\"af-sp\" data-a=\"speed\" title=\"速度\">' +\n      '        <option value=\"0.5\">0.5×<\/option><option value=\"1\" selected>1×<\/option>' +\n      '        <option value=\"1.5\">1.5×<\/option><option value=\"2\">2×<\/option>' +\n      '      <\/select>' +\n      '    <\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-rail\"><\/div>' +\n      '  <div class=\"af-prog\"><i><\/i><\/div>' +\n      '  <div class=\"af-stage\"><\/div>' +\n      '  <div class=\"af-meta\">' +\n      '    <div class=\"af-note\"><\/div>' +\n      '    <div class=\"af-stats\"><\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-count\"><\/div>' +\n      '<\/div>';\n\n    var $ = function (sel) { return mount.querySelector(sel); };\n    var stageEl = $('.af-stage');\n    var railEl = $('.af-rail');\n    var progEl = $('.af-prog i');\n    var noteEl = $('.af-note');\n    var statsEl = $('.af-stats');\n    var countEl = $('.af-count');\n    var playBtn = $('[data-a=\"play\"]');\n\n    /* ---- 阶段轨道 ---- */\n    var nodeEls = stages.map(function (s, i) {\n      var b = document.createElement('button');\n      b.type = 'button';\n      b.className = 'af-node';\n      b.innerHTML = '<span class=\"af-n\">' + (i + 1) + '<\/span>' +\n        '<span class=\"af-nm\">' + G.esc(s.name) + '<\/span>' +\n        (s.tag ? '<span class=\"af-tg\">' + G.esc(s.tag) + '<\/span>' : '');\n      b.addEventListener('click', function () { goto(i); });\n      railEl.appendChild(b);\n      return b;\n    });\n\n    function goto(i) {\n      var ni = Math.max(0, Math.min(stages.length - 1, i));\n      if (ni !== idx) { disposeDom(); }\n      idx = ni; t = 0; dirty = true;\n      render(true);\n    }\n\n    /* 精确跳到某阶段的某个进度（0—1）。测试与「定位某一帧」用。 */\n    function seek(i, tt) {\n      goto(i);\n      t = Math.max(0, Math.min(1, tt == null ? 0 : tt));\n      dirty = true;\n      render(true);\n    }\n\n    function disposeDom() {\n      if (domHandle && typeof domHandle.destroy === 'function') {\n        try { domHandle.destroy(); } catch (e) { }\n      }\n      domHandle = null; domStage = null;\n    }\n\n    function totalDur() {\n      var s = 0;\n      for (var i = 0; i < stages.length; i++) s += (stages[i].dur || 2200);\n      return s;\n    }\n\n    function elapsed() {\n      var s = 0;\n      for (var i = 0; i < idx; i++) s += (stages[i].dur || 2200);\n      return s + t * (stages[idx].dur || 2200);\n    }\n\n    function render(force) {\n      if (!dirty && !force) return;\n      dirty = false;\n      var st = stages[idx];\n      var res = {};\n\n      try {\n        if (typeof st.init === 'function') {\n          /* DOM 阶段：init 只在进入该阶段时跑一次 */\n          if (domStage !== idx) {\n            disposeDom();\n            stageEl.innerHTML = '';\n            var host = document.createElement('div');\n            host.className = 'af-dom';\n            stageEl.appendChild(host);\n            domHandle = st.init(host) || {};\n            domStage = idx;\n          }\n          res = domHandle.update ? (domHandle.update(t, { index: idx, stage: st, state: state, api: api }) || {}) : {};\n        } else {\n          res = st.draw(t, G, { index: idx, stage: st, state: state, api: api }) || {};\n          stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\">' +\n            (res.svg || '') + '<\/svg>';\n        }\n      } catch (err) {\n        disposeDom();\n        stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\">' +\n          G.panel(1, '这一段出了点问题', String(err && err.message || err), C.red) +\n          G.txt(500, 260, '（算法计算中断，其余阶段不受影响）', { size: 11, fill: C.ink3, anchor: 'middle' }) +\n          '<\/svg>';\n        res = {\n          stats: [],\n          note: '<b style=\"color:' + C.red + '\">绘制失败：<\/b>' + G.esc(String(err && err.message || err))\n        };\n      }\n\n      /* 统计格 */\n      var stats = res.stats || [];\n      var h = '';\n      for (var i = 0; i < stats.length; i++) {\n        var s0 = stats[i];\n        h += '<div class=\"af-stat' + (s0.tone ? ' t-' + s0.tone : '') + '\">' +\n          '<span class=\"k\">' + G.esc(s0.k) + '<\/span><b class=\"v\">' + G.esc(s0.v) + '<\/b><\/div>';\n      }\n      statsEl.innerHTML = h;\n\n      noteEl.innerHTML = res.note || '';\n\n      for (var j = 0; j < nodeEls.length; j++) {\n        nodeEls[j].className = 'af-node' + (j === idx ? ' on' : (j < idx ? ' done' : ''));\n      }\n      countEl.textContent = '第 ' + (idx + 1) + ' / ' + stages.length + ' 步 · ' + (st.name || '');\n\n      progEl.style.width = (elapsed() / totalDur() * 100).toFixed(2) + '%';\n\n      playBtn.textContent = playing ? '❚❚' : '▶';\n      playBtn.title = playing ? '暂停' : '播放';\n    }\n\n    /* ---- 播放循环 ---- */\n    function tick(ts) {\n      raf = requestAnimationFrame(tick);\n      if (!lastTs) lastTs = ts;\n      var dt = Math.min(120, ts - lastTs);\n      lastTs = ts;\n      if (playing) {\n        var dur = stages[idx].dur || 2200;\n        t += (dt * speed) / dur;\n        if (t >= 1) {\n          if (idx < stages.length - 1) { disposeDom(); idx++; t = 0; }\n          else if (opts.loop !== false) { disposeDom(); idx = 0; t = 0; }\n          else { t = 1; playing = false; }\n        }\n        dirty = true;\n      }\n      if (dirty) render();\n    }\n\n    /* ---- 控制 ---- */\n    mount.querySelectorAll('.af-b, .af-sp').forEach(function (btn) {\n      btn.addEventListener('click', function () {\n        var a = btn.getAttribute('data-a');\n        if (a === 'play') { playing = !playing; lastTs = 0; dirty = true; render(); }\n        else if (a === 'reset') { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); }\n        else if (a === 'prev') { if (t > 0.12) { t = 0; } else { goto(idx - 1); } dirty = true; render(); }\n        else if (a === 'next') { goto(idx + 1); }\n        else if (a === 'speed') { speed = parseFloat(btn.value) || 1; }\n      });\n    });\n    var sp = mount.querySelector('[data-a=\"speed\"]');\n    if (sp) sp.addEventListener('change', function () { speed = parseFloat(this.value) || 1; });\n\n    /* ---- 对外 API ---- */\n    var api = {\n      goto: goto,\n      seek: seek,\n      restart: function () { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); },\n      play: function () { playing = true; dirty = true; render(); },\n      pause: function () { playing = false; dirty = true; render(); },\n      refresh: function () { dirty = true; render(); },\n      get index() { return idx; },\n      setData: function (k, v) { state[k] = v; dirty = true; },\n      getData: function (k) { return state[k]; },\n      destroy: function () {\n        if (raf) cancelAnimationFrame(raf);\n        raf = null;\n        disposeDom();\n        mount.innerHTML = '';\n      }\n    };\n    if (opts.onReady) opts.onReady(api);\n\n    render(true);\n    raf = requestAnimationFrame(tick);\n    return api;\n  }\n\n  global.AFlow = { create: create, C: C, G: G, COLS: COLS };\n})(typeof window !== 'undefined' ? window : this);\n"},{"name":"demo/aiq.css","mime":"text/css","data":"/* =========================================================\n   AI 三问 · 可运行示范页通用区块\n   ---------------------------------------------------------\n   01 为什么（传统做法 vs AI 做法的同一段数据对照）\n   02 是什么（把业务对象翻译成算法可处理的形式）\n   03 怎样实现（五步工程路线，可跳到下方逐帧解剖）\n   依赖各包 demo.css 里的 --jade / --clay / --blue / --ink*\n   ========================================================= */\n\n.aiq {\n  margin: 0 0 18px; padding: 15px 18px 16px;\n  background: linear-gradient(180deg, #fbfaf6 0%, #ffffff 52%);\n  border: 1px solid var(--line, #e9e4d8); border-radius: 12px;\n}\n.aiq-top { display: flex; align-items: flex-start; gap: 10px; margin-bottom: 12px; }\n.aiq-chip {\n  flex: none; font-size: 10px; font-weight: 700; letter-spacing: .12em;\n  color: var(--jade, #2f7d6b); background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  border-radius: 999px; padding: 3px 9px; margin-top: 1px;\n}\n.aiq-lede { margin: 0; font-size: 13px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-lede b { color: var(--ink, #242b2e); }\n\n.aiq-grid { display: grid; grid-template-columns: 1.32fr 1fr 1fr; gap: 11px; }\n@media (max-width: 1040px) and (min-width: 760px) {\n  .aiq-grid { grid-template-columns: 1fr 1fr; grid-template-areas: \"a a\" \"b c\"; }\n  .aiq-card.q1 { grid-area: a; }\n  .aiq-card.q2 { grid-area: b; }\n  .aiq-card.q3 { grid-area: c; }\n}\n@media (max-width: 759px) { .aiq-grid { grid-template-columns: 1fr; } }\n.aiq-foot { margin: auto 0 0; padding-top: 2px; font-size: 10.5px; line-height: 1.5; color: var(--ink-4, #9ba3a9); }\n\n.aiq-card {\n  display: flex; flex-direction: column; gap: 9px;\n  border: 1px solid var(--line, #e9e4d8); border-radius: 10px;\n  background: #fff; padding: 11px 12px 11px;\n}\n.aiq-hd {\n  display: flex; align-items: center; gap: 7px;\n  padding-bottom: 8px; border-bottom: 1px dashed var(--line, #e9e4d8);\n}\n.aiq-hd .n {\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 10.5px; font-weight: 700; color: #fff;\n  border-radius: 5px; padding: 2px 6px; line-height: 1.5;\n}\n.aiq-hd > div { display: flex; align-items: baseline; gap: 4px; }\n.aiq-hd b { font-size: 14px; color: var(--ink, #242b2e); letter-spacing: .01em; }\n.aiq-hd em {\n  font-style: normal; font-size: 9px; letter-spacing: .16em; color: var(--ink-4, #9ba3a9);\n}\n.aiq-card.q1 .aiq-hd .n { background: var(--clay, #b26a39); }\n.aiq-card.q2 .aiq-hd .n { background: var(--blue, #41699b); }\n.aiq-card.q3 .aiq-hd .n { background: var(--jade, #2f7d6b); }\n\n/* ---------- 01 为什么：曲线对照 ---------- */\n.aiq-switch {\n  display: inline-flex; align-self: flex-start; gap: 2px; padding: 2px;\n  background: var(--card, #fbfaf6); border: 1px solid var(--line, #e9e4d8); border-radius: 999px;\n}\n.aiq-switch button {\n  font: inherit; font-size: 11.5px; line-height: 1.5; cursor: pointer;\n  border: 0; background: transparent; color: var(--ink-3, #79828a);\n  padding: 3px 11px; border-radius: 999px; transition: all .15s;\n}\n.aiq-switch button:hover { color: var(--ink, #242b2e); }\n.aiq-switch button.on {\n  background: #fff; color: var(--ink, #242b2e); font-weight: 600;\n  box-shadow: 0 1px 3px rgba(0, 0, 0, .08);\n}\n.aiq-fig { margin: 1px 0 0; }\n.aiq-fig svg { display: block; width: 100%; height: auto; }\n\n.aiq-nums {\n  display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px;\n  margin: 0; padding: 0; list-style: none;\n}\n.aiq-nums li {\n  background: var(--card, #fbfaf6); border: 1px solid #efeadf; border-radius: 7px;\n  padding: 5px 6px 6px; text-align: center;\n}\n.aiq-nums b {\n  display: block; font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 14.5px; line-height: 1.25; color: var(--ink-2, #4d565b);\n  font-variant-numeric: tabular-nums; transition: color .2s;\n}\n.aiq-nums span { display: block; font-size: 10px; color: var(--ink-3, #79828a); line-height: 1.35; margin-top: 2px; }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"good\"] b { color: var(--jade, #2f7d6b); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"bad\"] b { color: var(--clay, #b26a39); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"neut\"] b { color: var(--ink, #242b2e); }\n\n.aiq-note { margin: 0; font-size: 11.5px; line-height: 1.62; color: var(--ink-3, #79828a); }\n.aiq-note b { color: var(--ink-2, #4d565b); }\n.aiq-note .hl-bad { color: var(--clay, #b26a39); font-weight: 600; }\n.aiq-note .hl-good { color: var(--jade, #2f7d6b); font-weight: 600; }\n\n/* ---------- 02 是什么：翻译管线 + 式子 ---------- */\n.aiq-say { margin: 0; font-size: 12.5px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-say b { color: var(--ink, #242b2e); }\n.aiq-pipe { display: flex; flex-direction: column; }\n.aiq-pipe .p {\n  position: relative; padding: 5px 8px 5px 27px; border-radius: 6px;\n  background: var(--card, #fbfaf6); font-size: 11.5px; line-height: 1.5; color: var(--ink-3, #79828a);\n}\n.aiq-pipe .p i {\n  position: absolute; left: 8px; top: 6px; font-style: normal;\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px;\n  color: var(--blue, #41699b); font-weight: 700; letter-spacing: .02em;\n}\n.aiq-pipe .p b { color: var(--ink-2, #4d565b); font-weight: 600; }\n.aiq-pipe .ar { display: grid; place-items: center; height: 11px; }\n.aiq-pipe .ar::before {\n  content: \"\"; width: 1px; height: 7px; background: #ddd6c8;\n  box-shadow: 0 7px 0 -2px #ddd6c8;\n}\n.aiq-eq {\n  margin: 0; padding: 6px 9px; border-radius: 7px;\n  background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 11px; line-height: 1.8; color: #1f5f4d;\n  overflow-x: auto; white-space: nowrap;\n}\n.aiq-eq em { font-style: normal; color: #5f8f80; font-size: 10px; }\n.aiq-fit { margin: 0; padding: 0; list-style: none; font-size: 11.5px; line-height: 1.56; color: var(--ink-2, #4d565b); }\n.aiq-fit li { position: relative; padding-left: 15px; }\n.aiq-fit li + li { margin-top: 2px; }\n.aiq-fit li i { position: absolute; left: 0; top: 0; font-style: normal; font-weight: 700; }\n.aiq-fit .y i { color: var(--jade, #2f7d6b); }\n.aiq-fit .n i { color: var(--clay, #b26a39); }\n\n/* ---------- 03 怎样实现：五步 + 跳转 ---------- */\n.aiq-steps { margin: 0; padding: 0; list-style: none; counter-reset: aiqs; }\n.aiq-steps li {\n  position: relative; padding-left: 20px;\n  font-size: 11.5px; line-height: 1.55; color: var(--ink-2, #4d565b);\n}\n.aiq-steps li + li { margin-top: 5px; }\n.aiq-steps li::before {\n  counter-increment: aiqs; content: counter(aiqs);\n  position: absolute; left: 0; top: 1px; width: 14px; height: 14px;\n  border-radius: 50%; background: var(--jade-bg, #e6f1ec); color: var(--jade, #2f7d6b);\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px; font-weight: 700;\n  display: grid; place-items: center;\n}\n.aiq-steps li b { color: var(--ink, #242b2e); font-weight: 600; }\n.aiq-steps li code {\n  font-family: ui-monospace, Consolas, monospace; font-size: 10px;\n  background: #f3f0e8; border-radius: 3px; padding: 0 3px; color: #5c666b;\n}\n.aiq-jump {\n  margin-top: auto; padding-top: 8px; border-top: 1px dashed var(--line, #e9e4d8);\n  display: flex; align-items: center; justify-content: space-between; gap: 8px;\n}\n.aiq-jump span { font-size: 11px; color: var(--ink-4, #9ba3a9); }\n.aiq-jump a {\n  font-size: 11.5px; font-weight: 600; color: var(--jade, #2f7d6b);\n  text-decoration: none; white-space: nowrap;\n}\n.aiq-jump a:hover { color: #1f5f4d; text-decoration: underline; }\n\n/* 折叠态的三问（窄屏或用户收起时） */\n@media (max-width: 720px) {\n  .aiq { padding: 13px 12px 14px; }\n  .aiq-top { flex-direction: column; gap: 6px; }\n  .aiq-nums b { font-size: 13.5px; }\n}\n\n/* ---------- 03 卡内的踩坑提示 ---------- */\n.aiq-warn {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: var(--clay-bg, #f7ece2); border: 1px solid #eed9c6;\n  font-size: 11.5px; line-height: 1.6; color: #8a4f28;\n}\n.aiq-warn b { display: block; font-size: 10px; letter-spacing: .06em; color: var(--clay, #b26a39); margin-bottom: 2px; }\n\n/* ---------- 01 卡的对比表（没有可画的数字时用） ---------- */\n.aiq-tbl { width: 100%; border-collapse: collapse; font-size: 11.5px; }\n.aiq-tbl th {\n  font-size: 9.5px; font-weight: 600; color: var(--ink-4, #9ba3a9);\n  text-align: left; padding: 0 6px 5px; border-bottom: 1px solid var(--line, #e9e4d8);\n  letter-spacing: .02em;\n}\n.aiq-tbl th:first-child { padding-left: 0; }\n.aiq-tbl th:nth-child(2) { color: #8a9099; }\n.aiq-tbl th:nth-child(3) { color: var(--jade, #2f7d6b); }\n.aiq-tbl td {\n  padding: 5px 6px; border-bottom: 1px dashed #f2eee4;\n  color: var(--ink-2, #4d565b); line-height: 1.45; vertical-align: top;\n}\n.aiq-tbl td:first-child { padding-left: 0; color: var(--ink-3, #79828a); font-size: 11px; white-space: nowrap; }\n.aiq-tbl td:nth-child(2) { color: #7b838a; }\n.aiq-tbl td:nth-child(3) { color: #1f5f4d; font-weight: 500; }\n.aiq-tbl tr:last-child td { border-bottom: 0; }\n\n/* ---------- 01 卡的「代价」补充（填满短卡，也把边界说清） ---------- */\n.aiq-cost {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: #f4f2ea; border: 1px solid #e8e3d5;\n  font-size: 11.5px; line-height: 1.6; color: #5f676c;\n}\n.aiq-cost b { display: block; font-size: 10px; letter-spacing: .06em; color: #8a9099; margin-bottom: 2px; }\n"},{"name":"demo/aiq.js","mime":"text/javascript","data":"/* =========================================================\n   AI 三问 · 交互（只服务 01「为什么」卡的曲线对照）\n   ---------------------------------------------------------\n   同一段数据、同一条劣化曲线，切换「传统做法 / AI 做法」：\n   传统只在越过阈值那一刻报警；AI 在曲线还落在正常区间时就\n   从「偏离自身基线」的趋势里看出苗头。图上同时给出两处标记、\n   提前量与三个指标数字。\n   无依赖，data-* 配置，多实例安全。\n   ========================================================= */\n(function () {\n  'use strict';\n  var NS = 'http://www.w3.org/2000/svg';\n\n  function mk(name, attrs) {\n    var e = document.createElementNS(NS, name);\n    for (var k in attrs) if (attrs.hasOwnProperty(k)) e.setAttribute(k, attrs[k]);\n    return e;\n  }\n  function txt(s, x, y, o) {\n    var t = mk('text', {\n      x: x, y: y,\n      'font-size': (o && o.size) || 9.5,\n      fill: (o && o.fill) || '#79828a',\n      'text-anchor': (o && o.anchor) || 'start',\n      'font-family': 'ui-monospace, \"SF Mono\", Consolas, monospace',\n      'font-weight': (o && o.weight) || 400\n    });\n    t.textContent = s;\n    return t;\n  }\n\n  /* 曲线：t∈[0,100] → 归一化高度 v∈[0,1]（1=顶部） */\n  function valAt(t, shape, onset) {\n    var a;\n    if (t <= onset) a = 0.295 + 0.095 * (t / Math.max(1, onset));\n    else a = 0.39 + 0.55 * Math.pow((t - onset) / (100 - onset), 1.55);\n    return shape === 'fall' ? 1 - a : a;\n  }\n\n  var W = 420, H = 150, L = 30, R = 10, T = 12, B = 32;\n  function xOf(t) { return L + t / 100 * (W - L - R); }\n  function yOf(v) { return (H - B) - v * ((H - B) - T); }\n\n  /* 条形对比：同一批井/同一批任务，旧做法与新做法的指标代差 */\n  function drawBar(box, mode, cfg) {\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var rows = cfg.rows;\n    var W2 = 372, H2 = 150, TOP = 14, RH = 40, LAB = 92, BARX = 92, BARW = 186;\n    var svg = mk('svg', { viewBox: '0 0 ' + W2 + ' ' + H2, role: 'img' });\n    svg.setAttribute('aria-label', '旧做法与新做法的指标对比');\n\n    var i, r, oldOn = mode === 'old';\n    for (i = 0; i < rows.length; i++) {\n      r = rows[i];\n      var y = TOP + i * RH;\n      svg.appendChild(txt(r[0], 2, y + 11, { size: 10, fill: '#4d565b' }));\n      if (r[4]) svg.appendChild(txt(r[4], 2, y + 24, { size: 8.5, fill: '#9ba3a9' }));\n\n      /* 行首两枚色条：旧 / 新 */\n      svg.appendChild(mk('rect', { x: 0, y: y + 5, width: 2, height: 9, fill: '#8a9099', opacity: oldOn ? 0.9 : 0.25 }));\n      svg.appendChild(mk('rect', { x: 0, y: y + 20, width: 2, height: 9, fill: '#2f7d6b', opacity: oldOn ? 0.25 : 0.9 }));\n\n      /* 纯文本行（无数字可画条） */\n      if (!r[5]) {\n        svg.appendChild(txt(r[1], BARX, y + 12, { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 600 : 400 }));\n        svg.appendChild(txt(r[2], BARX, y + 27, { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 600 }));\n        continue;\n      }\n\n      /* 每行按自身量级归一：不同指标量纲不同，跨行比较没有意义 */\n      var rmax = Math.max(r[1], r[2]) || 1;\n      var wOld = Math.max(2, r[1] / rmax * BARW), wNew = Math.max(2, r[2] / rmax * BARW);\n      var unit = r[3] === '%' ? '%' : (r[3] ? ' ' + r[3] : '');\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 4, width: wOld, height: 9, rx: 2, fill: '#8a9099', opacity: oldOn ? 0.85 : 0.22 }));\n      svg.appendChild(txt(fmt(r[1]) + unit, BARX + BARW + 8, y + 12,\n        { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 700 : 400 }));\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 19, width: wNew, height: 9, rx: 2, fill: '#2f7d6b', opacity: oldOn ? 0.22 : 0.88 }));\n      svg.appendChild(txt(fmt(r[2]) + unit, BARX + BARW + 8, y + 27,\n        { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 700 }));\n    }\n\n    /* 图例 */\n    svg.appendChild(mk('rect', { x: BARX, y: H2 - 9, width: 8, height: 3, fill: '#8a9099', opacity: 0.85 }));\n    svg.appendChild(txt('旧做法', BARX + 12, H2 - 4, { size: 8.5, fill: '#79828a' }));\n    svg.appendChild(mk('rect', { x: BARX + 52, y: H2 - 9, width: 8, height: 3, fill: '#2f7d6b', opacity: 0.88 }));\n    svg.appendChild(txt('新做法', BARX + 64, H2 - 4, { size: 8.5, fill: '#79828a' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n  function fmt(v) {\n    var n = Number(v);\n    if (!isFinite(n)) return String(v);\n    return Math.abs(n) >= 100 ? n.toFixed(0) : (Math.abs(n) >= 10 ? n.toFixed(n % 1 ? 1 : 0) : n.toFixed(n % 1 ? 1 : 0));\n  }\n\n  function draw(box, mode, cfg) {\n    if (cfg.kind === 'bar') { drawBar(box, mode, cfg); return; }\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var svg = mk('svg', { viewBox: '0 0 ' + W + ' ' + H, role: 'img' });\n    svg.setAttribute('aria-label', '传统做法与 AI 做法的检出时机对比');\n\n    /* 网格 */\n    for (var g = 1; g <= 3; g++) {\n      svg.appendChild(mk('line', {\n        x1: L, y1: yOf(0.24 * g), x2: W - R, y2: yOf(0.24 * g),\n        stroke: '#f1ede2', 'stroke-width': 1\n      }));\n    }\n\n    /* 正常区间带 */\n    var lo = cfg.bandLo, hi = cfg.bandHi;\n    svg.appendChild(mk('rect', {\n      x: L, y: yOf(hi), width: W - L - R, height: Math.max(2, yOf(lo) - yOf(hi)),\n      fill: '#2f7d6b', opacity: 0.07\n    }));\n    svg.appendChild(txt('正常区间', W - R - 3, yOf(hi) + 9, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    /* 报警阈值 */\n    svg.appendChild(mk('line', {\n      x1: L, y1: yOf(cfg.thr), x2: W - R, y2: yOf(cfg.thr),\n      stroke: '#b26a39', 'stroke-width': 1.1, 'stroke-dasharray': '4 3', opacity: 0.6\n    }));\n    svg.appendChild(txt('阈值 θ', W - R - 3, yOf(cfg.thr) - 4, { anchor: 'end', size: 8.5, fill: '#b26a39' }));\n\n    /* 曲线 */\n    var d = '', i, v;\n    for (i = 0; i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      d += (i ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: d, fill: 'none', stroke: '#4d565b', 'stroke-width': 1.7,\n      'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 劣化起点 */\n    svg.appendChild(mk('line', {\n      x1: xOf(cfg.onset), y1: yOf(cfg.thr) - 2, x2: xOf(cfg.onset), y2: yOf(0.06),\n      stroke: '#cfc9bb', 'stroke-width': 1, 'stroke-dasharray': '2 3'\n    }));\n\n    /* 从判定点起，曲线高亮 */\n    var from = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var dd = '';\n    for (i = Math.round(from); i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      dd += (dd ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: dd, fill: 'none',\n      stroke: mode === 'new' ? '#2f7d6b' : '#b26a39',\n      'stroke-width': 2.6, 'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 底部时间轴上的「提前量」量尺 */\n    var yB = H - 15;\n    if (mode === 'new' && cfg.newAt < cfg.oldAt) {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.newAt), y1: yB, x2: xOf(cfg.oldAt), y2: yB,\n        stroke: '#2f7d6b', 'stroke-width': 2.4, opacity: 0.3, 'stroke-linecap': 'round'\n      }));\n      [cfg.newAt, cfg.oldAt].forEach(function (t) {\n        svg.appendChild(mk('line', {\n          x1: xOf(t), y1: yB - 3.5, x2: xOf(t), y2: yB + 3.5,\n          stroke: '#2f7d6b', 'stroke-width': 1.2\n        }));\n      });\n      svg.appendChild(txt('提前 ' + cfg.days + ' 天', (xOf(cfg.newAt) + xOf(cfg.oldAt)) / 2, yB - 5,\n        { anchor: 'middle', size: 9, fill: '#2f7d6b', weight: 600 }));\n    } else {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.oldAt), y1: yB, x2: W - R, y2: yB,\n        stroke: '#b26a39', 'stroke-width': 2.4, opacity: 0.28, 'stroke-linecap': 'round'\n      }));\n      svg.appendChild(txt('这段没有任何预警', W - R - 3, yB - 5,\n        { anchor: 'end', size: 9, fill: '#b26a39', weight: 600 }));\n    }\n\n    /* 判定点 */\n    var tx = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var px = xOf(tx), py = yOf(valAt(tx, cfg.shape, cfg.onset));\n    var col = mode === 'new' ? '#2f7d6b' : '#b26a39';\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 6.5, fill: col, opacity: 0.15 }));\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 3.2, fill: col, stroke: '#fff', 'stroke-width': 1.3 }));\n\n    /* 标签固定在左上角，用细引线指到判定点：两种模式切换时位置不跳，便于对比 */\n    var label = mode === 'new' ? '这里就预警' : '越限才发现';\n    var tw = label.length * 9 + 11, th = 15;\n    var tX = L + 3, tY = T + 1;\n    svg.appendChild(mk('line', {\n      x1: tX + tw / 2, y1: tY + th, x2: px, y2: py - 5,\n      stroke: col, 'stroke-width': 0.8, 'stroke-dasharray': '2 3', opacity: 0.45\n    }));\n    svg.appendChild(mk('rect', {\n      x: tX, y: tY, width: tw, height: th, rx: 3.5,\n      fill: '#fffdf7', stroke: col, 'stroke-width': 0.8, 'stroke-opacity': 0.4\n    }));\n    svg.appendChild(txt(label, tX + 6, tY + 11, { size: 9, fill: col, weight: 600 }));\n\n    /* 轴与单位 */\n    svg.appendChild(txt('时间 →', L, H - 3, { size: 8.5, fill: '#9ba3a9' }));\n    svg.appendChild(txt(cfg.unit, W - R, T + 2, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n\n  function init(box) {\n    var cfg = {\n      shape: box.getAttribute('data-shape') || 'rise',\n      unit: box.getAttribute('data-unit') || '',\n      onset: parseFloat(box.getAttribute('data-onset')) || 55,\n      thr: parseFloat(box.getAttribute('data-thr')) || 0.72,\n      oldAt: parseFloat(box.getAttribute('data-old-at')) || 88,\n      newAt: parseFloat(box.getAttribute('data-new-at')) || 60,\n      days: box.getAttribute('data-days') || '',\n      kind: box.getAttribute('data-kind') || 'trend',\n      rows: (box.getAttribute('data-rows') || '').split(';').filter(function (x) { return x.trim(); }).map(function (x) {\n        var p = x.split('|');\n        var num = isFinite(parseFloat(p[1])) && isFinite(parseFloat(p[2]));\n        return [p[0] || '', num ? parseFloat(p[1]) : (p[1] || ''), num ? parseFloat(p[2]) : (p[2] || ''), p[3] || '', p[4] || '', num];\n      }),\n      bandLo: parseFloat(box.getAttribute('data-band-lo')) || 0.26,\n      bandHi: parseFloat(box.getAttribute('data-band-hi')) || 0.46\n    };\n    var btns = box.querySelectorAll('.aiq-switch button');\n    var nums = box.querySelectorAll('.aiq-nums b[data-old]');\n    var notes = box.querySelectorAll('.aiq-note [data-v]');\n\n    function set(mode) {\n      box.setAttribute('data-mode', mode);\n      [].forEach.call(btns, function (b) { b.classList.toggle('on', b.getAttribute('data-v') === mode); });\n      [].forEach.call(nums, function (n) {\n        var v = n.getAttribute('data-' + (mode === 'old' ? 'old' : 'new'));\n        if (v != null && v !== '') n.textContent = v;\n      });\n      [].forEach.call(notes, function (n) { n.hidden = n.getAttribute('data-v') !== mode; });\n      draw(box, mode, cfg);\n    }\n\n    if (!btns.length) { set('new'); return; }\n    [].forEach.call(btns, function (b) {\n      b.addEventListener('click', function () { set(b.getAttribute('data-v')); });\n    });\n    set('old');\n  }\n\n  function boot() {\n    [].forEach.call(document.querySelectorAll('[data-aiq]'), init);\n  }\n  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);\n  else boot();\n})();\n"},{"name":"demo/demo.css","mime":"text/css","data":"/* =========================================================\n   地质剖面遥感解译 · 示范页样式（整页模式，沙箱 iframe）\n   浅色主题：全部使用设计令牌 / 低饱和浅色 hex\n   ========================================================= */\n:root {\n  --jade: #2f7d6b;\n  --jade-bg: #e6f1ec;\n  --clay: #b26a39;\n  --clay-bg: #f7ece2;\n  --blue: #41699b;\n  --blue-bg: #e7eef9;\n  --ink: #242b2e;\n  --ink-2: #4d565b;\n  --ink-3: #79828a;\n  --ink-4: #9ba3a9;\n  --line: #e9e4d8;\n  --card: #fbfaf6;\n  --bg: #faf9f4;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  padding: 20px 22px 26px;\n  background: var(--bg);\n  color: var(--ink);\n  font: 14.5px/1.7 -apple-system, \"Segoe UI\", \"Microsoft YaHei\", system-ui, sans-serif;\n}\n\n/* ---------- 头部 ---------- */\n.hd { margin-bottom: 18px; }\n.kicker { font-size: 10.5px; letter-spacing: .14em; color: var(--jade); font-weight: 700; }\n.hd h1 { margin: 4px 0 6px; font-size: 21px; color: var(--ink); }\n.hd .sub { margin: 0; color: var(--ink-3); font-size: 13.5px; }\n\n/* ---------- 区块 ---------- */\n.sec {\n  margin-bottom: 26px; padding: 18px 20px;\n  background: var(--card); border: 1px solid var(--line); border-radius: 12px;\n}\n.sec-hd { margin-bottom: 12px; }\n.sec-no { font-size: 10.5px; letter-spacing: .12em; color: var(--ink-4); font-weight: 700; text-transform: uppercase; }\n.sec-hd h2 { margin: 3px 0 6px; font-size: 17px; color: var(--ink); }\n.sec-hd .leadline { margin: 0; color: var(--ink-3); font-size: 13px; }\n.sec-hd .leadline b { color: var(--ink); }\n\n/* ---------- 图例 ---------- */\n.legend { display: flex; flex-wrap: wrap; gap: 8px 14px; margin: 8px 0 4px; }\n.legend .lg { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; color: var(--ink-2); }\n.legend .lg i { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }\n\n/* ---------- 控件 ---------- */\n.ctl { display: flex; flex-wrap: wrap; gap: 14px 24px; align-items: center; margin-bottom: 12px; padding: 10px 12px; background: var(--bg); border: 1px solid var(--line); border-radius: 10px; }\n.ctl .btns { display: flex; flex-wrap: wrap; gap: 6px; }\n.ctl .btns button { font: inherit; font-size: 12.5px; padding: 5px 12px; border-radius: 8px; border: 1px solid var(--line); background: #fff; color: var(--ink-2); cursor: pointer; }\n.ctl .btns button.on, .ctl .btns button:hover { background: var(--jade); color: #fff; border-color: var(--jade); }\n.ctl .sl { display: flex; flex-direction: column; gap: 3px; min-width: 180px; }\n.ctl .sl label { font-size: 12.5px; color: var(--ink-2); display: flex; justify-content: space-between; align-items: center; }\n.ctl .sl output { font-family: ui-monospace, monospace; font-size: 13px; color: var(--jade); font-weight: 600; }\n.ctl input[type=range] { width: 100%; accent-color: var(--jade); }\n\n/* ---------- SVG 图 ---------- */\n.chart-wrap { width: 100%; }\n.chart-wrap svg { width: 100%; height: auto; display: block; border: 1px solid var(--line); border-radius: 8px; background: #fff; }\n.fg { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n.fg .cap { font-size: 12px; color: var(--ink-3); text-align: center; margin-top: 6px; }\n@media (max-width:720px){ .fg { grid-template-columns: 1fr; } }\n\n/* ---------- 结果读数行 ---------- */\n.rrow { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 12px; }\n.ro { flex: 1; min-width: 130px; background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 8px 12px; }\n.ro .k { display: block; font-size: 11px; color: var(--ink-4); margin-bottom: 2px; }\n.ro b { font-size: 15px; color: var(--ink); }\n.ro b.good { color: var(--jade); }\n.ro b.warn { color: var(--clay); }\n\n/* ---------- 提示 / 折叠 ---------- */\n.tip { margin: 10px 0 0; font-size: 12.5px; color: var(--ink-3); background: var(--jade-bg); border-radius: 8px; padding: 8px 12px; }\n.details { margin-top: 12px; }\n.details summary { cursor: pointer; font-size: 13px; color: var(--jade); font-weight: 600; }\n\n/* 算法解剖引擎在 aflow.css 里；AI 三问在 aiq.css 里 */\n"},{"name":"demo/demo.js","mime":"text/javascript","data":"/* =========================================================\n   钻速预测与参数优化 · 示范脚本（整页模式，运行在沙箱 iframe 里）\n   ---------------------------------------------------------\n   三屏：\n   屏 1  钻速时序预测：随钻参数 → 钻速（时序回归）\n   屏 2  贝叶斯优化：参数空间（钻压×转速）找最优，兼顾风险\n   屏 3  保守 vs 最优参数：钻速对比 + 风险可控\n   所有计算都在浏览器里完成，纯前端。\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* =====================================================\n     纯模型层（Node 可 require 做单测；浏览器里继续往下走）\n     ===================================================== */\n  var Model = (function () {\n\n    function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n    function mulberry32(a) {\n      return function () {\n        a |= 0; a = a + 0x6D2B79F5 | 0;\n        var t = Math.imul(a ^ a >>> 15, 1 | a);\n        t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;\n        return ((t ^ t >>> 14) >>> 0) / 4294967296;\n      };\n    }\n\n    var PARAM_NAMES = ['钻压', '转速', '扭矩', '排量'];\n\n    /* -----------------------------------------------------\n       合成钻时序列\n       若干地层分段（每段可钻性不同），随钻参数 + 钻速随时间变化。\n       返回 { n, depth, wob(钻压), rpm(转速), tor(扭矩), dis(排量), rop(真值钻速) }\n       ----------------------------------------------------- */\n    function genDrill(n, seed) {\n      var rnd = mulberry32(seed || 20261131);\n      var depth = [], wob = [], rpm = [], tor = [], dis = [], rop = [];\n      var segs = [];\n      var ns = 3 + Math.floor(rnd() * 3);\n      for (var i = 0; i < ns; i++) {\n        segs.push({ s: Math.floor(rnd() * n), dur: 0.2 + rnd() * 0.4, r: 0.4 + rnd() * 0.8 });\n      }\n      var lastRop = 8;\n      for (var t = 0; t < n; t++) {\n        depth.push(t);\n        var drift = 0;\n        for (var s = 0; s < segs.length; s++) {\n          var d = Math.abs(t - segs[s].s) / (segs[s].dur * n);\n          if (d < 1) drift += Math.sin(d * Math.PI) * segs[s].r;\n        }\n        var base = 10 + drift * 5 + Math.sin(t * 0.05) * 1.2;\n        wob.push(clamp(8 + (rnd() - 0.4) * 3 + Math.sin(t * 0.02) * 1.5, 5, 14));\n        rpm.push(clamp(50 + (rnd() - 0.4) * 12 + Math.cos(t * 0.03) * 6, 35, 75));\n        tor.push(clamp(2 + (rnd() - 0.5) * 0.8 + Math.abs(Math.sin(t * 0.04)) * 0.6, 1, 4));\n        dis.push(clamp(20 + (rnd() - 0.5) * 3, 15, 26));\n        var ropNow = clamp(base + (wob[t] - 10) * 0.4 + (rpm[t] - 55) * 0.12 + (rnd() - 0.5) * 1.5, 4, 20);\n        /* 平滑过渡 */\n        ropNow = lastRop * 0.3 + ropNow * 0.7;\n        lastRop = ropNow;\n        rop.push(ropNow);\n      }\n      return { n: n, depth: depth, wob: wob, rpm: rpm, tor: tor, dis: dis, rop: rop };\n    }\n\n    /* -----------------------------------------------------\n       钻速时序预测（模拟时序回归）\n       weight ∈ [0,1]：越接近 1 预测越贴近真值。\n       ----------------------------------------------------- */\n    function ropPredict(seq, weight) {\n      var n = seq.n;\n      var pred = new Float64Array(n);\n      var rnd = mulberry32(20261132);\n      for (var t = 0; t < n; t++) {\n        var trueRop = seq.rop[t];\n        var noise = (1 - weight) * 1.6 * (rnd() + rnd() - 1);\n        pred[t] = clamp(trueRop + noise, 2, 22);\n      }\n      return { pred: pred };\n    }\n\n    function ropEval(seq, pred) {\n      var n = seq.n;\n      var se = 0;\n      for (var i = 0; i < n; i++) se += (seq.rop[i] - pred[i]) * (seq.rop[i] - pred[i]);\n      var rmse = Math.sqrt(se / n);\n      var mp = 0, mq = 0;\n      for (var j = 0; j < n; j++) { mp += seq.rop[j]; mq += pred[j]; }\n      mp /= n; mq /= n;\n      var cov = 0, vp = 0, vq = 0;\n      for (var k = 0; k < n; k++) { cov += (seq.rop[k] - mp) * (pred[k] - mq); vp += (seq.rop[k] - mp) * (seq.rop[k] - mp); vq += (pred[k] - mq) * (pred[k] - mq); }\n      var corr = cov / (Math.sqrt(vp) * Math.sqrt(vq) + 1e-9);\n      return { rmse: rmse, corr: corr };\n    }\n\n    /* -----------------------------------------------------\n       钻速代理模型：rop = 函数(钻压, 转速)\n       中间有最优区，边缘有高风险区（钻头磨损）。\n       ----------------------------------------------------- */\n    function ropModel(wob, rpm) {\n      var wobN = clamp((wob - 5) / 9, 0, 1);   /* 0..1 */\n      var rpmN = clamp((rpm - 35) / 40, 0, 1); /* 0..1 */\n      var peak = 18 * Math.exp(-((wobN - 0.55) * (wobN - 0.55)) / 0.08 - ((rpmN - 0.6) * (rpmN - 0.6)) / 0.1);\n      var base = 6 + wobN * 4 + rpmN * 3;\n      var risk = 0;\n      /* 高风险区：钻压过大或转速过高 */\n      if (wobN > 0.85) risk += 3 + (wobN - 0.85) * 12;\n      if (rpmN > 0.85) risk += 2 + (rpmN - 0.85) * 8;\n      var rop = clamp(base + peak - risk * 0.6, 0, 22);\n      return { rop: rop, risk: risk };\n    }\n\n    /* -----------------------------------------------------\n       贝叶斯优化（模拟）\n       nIter 轮采样，找最优（钻压,转速）。返回最优与轨迹。\n       ----------------------------------------------------- */\n    function bayesOptimize(nIter, seed) {\n      var rnd = mulberry32(seed || 20261133);\n      var best = null;\n      var trace = [];\n      var wob = 9, rpm = 55;\n      for (var i = 0; i < nIter; i++) {\n        /* 探索：围绕当前最优点加扰动 */\n        wob = clamp(wob + (rnd() - 0.5) * 2.4, 5, 14);\n        rpm = clamp(rpm + (rnd() - 0.5) * 18, 35, 75);\n        var r = ropModel(wob, rpm);\n        if (!best || (r.rop - r.risk * 0.4) > best.score) {\n          best = { wob: wob, rpm: rpm, rop: r.rop, risk: r.risk, score: r.rop - r.risk * 0.4 };\n        }\n        trace.push({ i: i, wob: wob, rpm: rpm, rop: r.rop, risk: r.risk });\n      }\n      return { best: best, trace: trace };\n    }\n\n    /* 保守参数 */\n    function conservativeParams() {\n      return { wob: 8.2, rpm: 48, label: '保守' };\n    }\n\n    return {\n      clamp: clamp, mulberry32: mulberry32, PARAM_NAMES: PARAM_NAMES,\n      genDrill: genDrill, ropPredict: ropPredict, ropEval: ropEval,\n      ropModel: ropModel, bayesOptimize: bayesOptimize, conservativeParams: conservativeParams\n    };\n  })();\n\n  /* Node 单测入口 */\n  if (typeof module !== 'undefined' && module.exports) {\n    module.exports = Model;\n    return;\n  }\n\n  /* =====================================================\n     浏览器接线（沙箱 iframe 内执行）\n     ===================================================== */\n  var doc = document;\n  var $ = function (id) { return doc.getElementById(id); };\n  var M = Model;\n\n  var state = {\n    weight: 0.7, nIter: 24, nWell: 40,\n    selPar: 0 /* 0 钻压 1 转速 2 扭矩 3 排量 */, segA: 0, segB: 1\n  };\n\n  var seq1 = M.genDrill(60, 20261131);\n  var pred1 = M.ropPredict(seq1, state.weight);\n\n  global.RemoteBridge = {\n    M: M,\n    genDrill: M.genDrill, ropPredict: M.ropPredict, ropEval: M.ropEval,\n    ropModel: M.ropModel, bayesOptimize: M.bayesOptimize, conservativeParams: M.conservativeParams,\n    live: function () {\n      return { weight: state.weight, nIter: state.nIter, nWell: state.nWell, selPar: state.selPar, segA: state.segA, segB: state.segB };\n    }\n  };\n\n  function num(v, d) { return v.toFixed(d == null ? 1 : d); }\n  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n  /* 折线图辅助 */\n  function linePath(arr, x0, y0, xScale, yScale, yMax, color, dash) {\n    var s = '<path d=\"M';\n    for (var i = 0; i < arr.length; i++) {\n      s += (x0 + i * xScale).toFixed(1) + ' ' + (y0 - arr[i] * yScale).toFixed(1);\n      if (i < arr.length - 1) s += ' L';\n    }\n    s += '\" fill=\"none\" stroke=\"' + color + '\" stroke-width=\"' + (dash ? 1.8 : 2) + '\"' + (dash ? ' stroke-dasharray=\"5 3\"' : '') + '/>';\n    return s;\n  }\n\n  /* ---------- 屏 1 渲染：钻速时序预测 ---------- */\n  function renderPred() {\n    seq1 = M.genDrill(60, 20261131);\n    pred1 = M.ropPredict(seq1, state.weight);\n    var ev = M.ropEval(seq1, pred1);\n    var n = seq1.n;\n    var H = 240, W = 360, x0 = 50, y0 = 18;\n    var xS = W / n, yS = 210 / 22;\n    var s = '<line x1=\"' + x0 + '\" y1=\"' + y0 + '\" x2=\"' + x0 + '\" y2=\"' + (y0 + H) + '\" stroke=\"#9ba3a9\" stroke-width=\"1\"/>';\n    s += '<line x1=\"' + x0 + '\" y1=\"' + (y0 + H) + '\" x2=\"' + (x0 + W) + '\" y2=\"' + (y0 + H) + '\" stroke=\"#9ba3a9\" stroke-width=\"1\"/>';\n    s += '<text x=\"' + (x0 + 10) + '\" y=\"' + (y0 + 12) + '\" font-size=\"9\" fill=\"#79828a\">钻速 m/h<\/text>';\n    s += '<text x=\"' + (x0 + W - 40) + '\" y=\"' + (y0 + H + 16) + '\" font-size=\"9\" fill=\"#79828a\">时间（采样点）<\/text>';\n    s += linePath(seq1.rop, x0, y0 + H, xS, yS, 22, '#2f7d6b', false);\n    s += linePath(pred1.pred, x0, y0 + H, xS, yS, 22, '#b26a39', true);\n    s += '<text x=\"' + (x0 + W + 10) + '\" y=\"' + (y0 + 20) + '\" font-size=\"9\" fill=\"#2f7d6b\" font-weight=\"700\">真实钻速<\/text>';\n    s += '<text x=\"' + (x0 + W + 10) + '\" y=\"' + (y0 + 36) + '\" font-size=\"9\" fill=\"#b26a39\" font-weight=\"700\">预测钻速<\/text>';\n    $('ropChart').innerHTML = s;\n    $('roRmse').textContent = 'RMSE ' + num(ev.rmse, 2) + ' m/h';\n    $('roCorr').textContent = '相关系数 ' + num(ev.corr, 2);\n    /* 参数曲线（切换显示） */\n    var par = [seq1.wob, seq1.rpm, seq1.tor, seq1.dis];\n    var parName = M.PARAM_NAMES[state.selPar];\n    var parMin = [5, 35, 1, 15], parMax = [14, 75, 4, 26];\n    var pH = 120, pW = 300, px0 = 50, py0 = 300;\n    var pS = 100 / (parMax[state.selPar] - parMin[state.selPar]);\n    var ps = '<line x1=\"' + px0 + '\" y1=\"' + py0 + '\" x2=\"' + (px0 + pW) + '\" y2=\"' + py0 + '\" stroke=\"#9ba3a9\" stroke-width=\"1\"/>';\n    ps += '<text x=\"' + px0 + '\" y=\"' + (py0 + 14) + '\" font-size=\"9\" fill=\"#79828a\">' + parName + ' 随时间<\/text>';\n    ps += linePath(par[state.selPar], px0, py0, pW / n, pS, 1, '#41699b', false);\n    $('parChart').innerHTML = ps;\n  }\n\n  /* ---------- 屏 2 渲染：贝叶斯优化 ---------- */\n  function renderOpt() {\n    /* 参数空间热力图 */\n    var W = 44, H = 34, cell = 6;\n    var wobMin = 5, wobMax = 14, rpmMin = 35, rpmMax = 75;\n    var s = '';\n    var maxRop = 0;\n    var grid = [];\n    for (var r = 0; r < H; r++) { grid[r] = []; for (var c = 0; c < W; c++) {\n      var wob = wobMin + (c / (W - 1)) * (wobMax - wobMin);\n      var rpm = rpmMin + (r / (H - 1)) * (rpmMax - rpmMin);\n      var m = M.ropModel(wob, rpm);\n      grid[r][c] = m.rop;\n      if (m.rop > maxRop) maxRop = m.rop;\n    }}\n    for (r = 0; r < H; r++) for (c = 0; c < W; c++) {\n      var v = grid[r][c] / (maxRop || 1);\n      var g = Math.round(90 + 150 * v);\n      var risk = M.ropModel(wobMin + (c / (W - 1)) * 9, rpmMin + (r / (H - 1)) * 40).risk;\n      var col;\n      if (risk > 4) col = 'rgb(180,96,86)';\n      else col = 'rgb(' + Math.round(230 - v * 130) + ',' + g + ',' + Math.round(230 - v * 120) + ')';\n      s += '<rect x=\"' + (c * cell) + '\" y=\"' + (r * cell) + '\" width=\"' + cell + '\" height=\"' + cell + '\" fill=\"' + col + '\"/>';\n    }\n    /* 贝叶斯优化轨迹 */\n    var opt = M.bayesOptimize(state.nIter, 20261133);\n    for (var i = 0; i < opt.trace.length; i++) {\n      var t = opt.trace[i];\n      var cx = ((t.wob - wobMin) / 9) * (W * cell);\n      var cy = ((t.rpm - rpmMin) / 40) * (H * cell);\n      s += '<circle cx=\"' + cx + '\" cy=\"' + cy + '\" r=\"2\" fill=\"none\" stroke=\"#24333a\" stroke-width=\"1\"/>';\n    }\n    var b = opt.best;\n    var bxc = ((b.wob - wobMin) / 9) * (W * cell);\n    var byc = ((b.rpm - rpmMin) / 40) * (H * cell);\n    s += '<circle cx=\"' + bxc + '\" cy=\"' + byc + '\" r=\"4\" fill=\"#24333a\" stroke=\"#fff\" stroke-width=\"1.5\"/>';\n    s += '<text x=\"' + bxc + '\" y=\"' + (byc - 6) + '\" font-size=\"8\" fill=\"#24333a\" text-anchor=\"middle\" font-weight=\"700\">最优<\/text>';\n    $('optChart').innerHTML = s;\n    $('roBest').textContent = '最优：钻压 ' + num(b.wob, 1) + ' · 转速 ' + num(b.rpm, 0) + ' → 钻速 ' + num(b.rop, 1) + ' m/h';\n    $('roRisk').textContent = '风险 ' + num(b.risk, 1) + '（' + (b.risk < 2 ? '低' : b.risk < 5 ? '中' : '高') + '）';\n    $('roIter').textContent = '迭代 ' + opt.trace.length + ' 轮';\n  }\n\n  /* ---------- 屏 3 渲染：保守 vs 最优 ---------- */\n  function renderCompare() {\n    var opt = M.bayesOptimize(40, 20261133);\n    var b = opt.best;\n    var cons = M.conservativeParams();\n    var ropCons = M.ropModel(cons.wob, cons.rpm);\n    var ropOpt = M.ropModel(b.wob, b.rpm);\n    var lift = ropOpt.rop / (ropCons.rop || 1) - 1;\n\n    var s = '';\n    /* 参数条对比 */\n    var rows = [\n      ['钻压 kN', cons.wob, b.wob, 5, 14],\n      ['转速 rpm', cons.rpm, b.rpm, 35, 75]\n    ];\n    var y = 20;\n    for (var i = 0; i < rows.length; i++) {\n      var r = rows[i];\n      s += '<text x=\"30\" y=\"' + (y + 14) + '\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">' + r[0] + '<\/text>';\n      var x0 = 130, w = 220;\n      var span = r[4] - r[3];\n      var c0 = x0 + ((r[1] - r[3]) / span) * w;\n      var c1 = x0 + ((r[2] - r[3]) / span) * w;\n      s += '<line x1=\"' + x0 + '\" y1=\"' + (y + 10) + '\" x2=\"' + (x0 + w) + '\" y2=\"' + (y + 10) + '\" stroke=\"#e9e4d8\" stroke-width=\"6\"/>';\n      s += '<circle cx=\"' + c0 + '\" cy=\"' + (y + 10) + '\" r=\"6\" fill=\"#41699b\"/><text x=\"' + (c0) + '\" y=\"' + (y - 2) + '\" font-size=\"8\" fill=\"#41699b\" text-anchor=\"middle\">保守<\/text>';\n      s += '<circle cx=\"' + c1 + '\" cy=\"' + (y + 10) + '\" r=\"6\" fill=\"#2f7d6b\"/><text x=\"' + (c1) + '\" y=\"' + (y + 28) + '\" font-size=\"8\" fill=\"#2f7d6b\" text-anchor=\"middle\">最优<\/text>';\n      y += 60;\n    }\n    /* 钻速对比柱 */\n    var x0 = 40, y0 = 160, cw = 120, ch = 150;\n    var maxRop = Math.max(ropCons.rop, ropOpt.rop, 1);\n    var hCons = ropCons.rop / maxRop * ch;\n    var hOpt = ropOpt.rop / maxRop * ch;\n    s += '<line x1=\"' + x0 + '\" y1=\"' + y0 + '\" x2=\"' + x0 + '\" y2=\"' + (y0 + ch) + '\" stroke=\"#9ba3a9\" stroke-width=\"1\"/>';\n    s += '<line x1=\"' + x0 + '\" y1=\"' + (y0 + ch) + '\" x2=\"' + (x0 + 340) + '\" y2=\"' + (y0 + ch) + '\" stroke=\"#9ba3a9\" stroke-width=\"1\"/>';\n    s += '<rect x=\"' + (x0 + 20) + '\" y=\"' + (y0 + ch - hCons) + '\" width=\"100\" height=\"' + hCons + '\" fill=\"#41699b\"/>';\n    s += '<text x=\"' + (x0 + 70) + '\" y=\"' + (y0 + ch - hCons - 6) + '\" font-size=\"10\" fill=\"#41699b\" text-anchor=\"middle\" font-weight=\"700\">' + num(ropCons.rop, 1) + '<\/text>';\n    s += '<text x=\"' + (x0 + 70) + '\" y=\"' + (y0 + ch + 16) + '\" font-size=\"9\" fill=\"#41699b\" text-anchor=\"middle\">保守参数<\/text>';\n    s += '<rect x=\"' + (x0 + 190) + '\" y=\"' + (y0 + ch - hOpt) + '\" width=\"100\" height=\"' + hOpt + '\" fill=\"#2f7d6b\"/>';\n    s += '<text x=\"' + (x0 + 240) + '\" y=\"' + (y0 + ch - hOpt - 6) + '\" font-size=\"10\" fill=\"#2f7d6b\" text-anchor=\"middle\" font-weight=\"700\">' + num(ropOpt.rop, 1) + '<\/text>';\n    s += '<text x=\"' + (x0 + 240) + '\" y=\"' + (y0 + ch + 16) + '\" font-size=\"9\" fill=\"#2f7d6b\" text-anchor=\"middle\">最优参数<\/text>';\n    s += '<text x=\"' + (x0 + 300) + '\" y=\"' + (y0 + 40) + '\" font-size=\"12\" fill=\"#b26a39\" font-weight=\"700\">+' + Math.round(lift * 100) + '%<\/text>';\n    $('cmpChart').innerHTML = s;\n    $('roLift').textContent = '钻速提升 ' + Math.round(lift * 100) + '%';\n    $('roRiskCmp').textContent = '风险：保守 ' + num(ropCons.risk, 1) + ' vs 最优 ' + num(ropOpt.risk, 1) + '（' + (ropOpt.risk <= ropCons.risk + 1 ? '风险可控' : '风险上升') + '）';\n  }\n\n  /* ---------- 事件绑定 ---------- */\n  function bind() {\n    var inWeight = $('inWeight');\n    if (inWeight) inWeight.addEventListener('input', function () {\n      state.weight = parseFloat(inWeight.value);\n      $('outWeight').textContent = num(state.weight, 2);\n      renderPred();\n    });\n    var inIter = $('inIter');\n    if (inIter) inIter.addEventListener('input', function () {\n      state.nIter = parseInt(inIter.value, 10);\n      $('outIter').textContent = String(state.nIter);\n      renderOpt();\n    });\n    var inPar = $('inPar');\n    if (inPar) inPar.addEventListener('input', function () {\n      state.selPar = parseInt(inPar.value, 10);\n      $('outPar').textContent = M.PARAM_NAMES[state.selPar];\n      renderPred();\n    });\n  }\n\n  /* 抽屉上报 */\n  function setupDrawer() {\n    if (window.parent === window) return;\n    var secs = [];\n    [['sec1', '钻速预测', 'predCtl'], ['sec2', '参数优化', 'optCtl'], ['sec3', '参数对比', 'cmpCtl']].forEach(function (s) {\n      var el = $(s[2]); if (!el) return;\n      el.querySelectorAll('input, button').forEach(function (c) {\n        if (c.type === 'range') c.setAttribute('value', c.value);\n      });\n      secs.push({ id: s[0], title: s[1], html: el.outerHTML, top: el.offsetTop, height: el.offsetHeight });\n    });\n    try { parent.postMessage({ __drawer: 'init', sections: secs }, '*'); } catch (e) {}\n    window.addEventListener('message', function (e) {\n      if (e.source !== window.parent) return;\n      var d = e.data;\n      if (!d || d.__drawer !== 'control') return;\n      var el = doc.querySelector('[data-ctl-id=\"' + d.id + '\"]');\n      if (!el) return;\n      if (el.type === 'range') { el.value = d.value; el.dispatchEvent(new Event('input', { bubbles: true })); }\n      else if (el.tagName === 'BUTTON') { el.click(); }\n    });\n  }\n\n  /* ---------- 启动 ---------- */\n  bind();\n  renderPred(); renderOpt(); renderCompare();\n  setupDrawer();\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/flow.js","mime":"text/javascript","data":"/* =========================================================\n   钻速预测与参数优化 · 算法解剖（时序回归 + 贝叶斯优化）\n   ---------------------------------------------------------\n   把「随钻参数 → 最优钻速」拆成 6 步，每一步都跑真代码：\n\n     ① 数据接入      钻时序列 + 井段划分\n     ② 时序特征      随钻参数 → 滑动窗口特征\n     ③ 钻速预测      参数序列 → 钻速（时序回归）\n     ④ 贝叶斯优化    参数空间找最优（兼顾风险）\n     ⑤ 保守 vs 最优  钻速对比 + 风险可控\n     ⑥ 部署与回流    方案 + 在线更新\n\n   依赖：window.RemoteBridge（demo.js 暴露的真模型）\n        window.AFlow（算法解剖引擎）\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  var B = global.RemoteBridge;\n  if (!B || !global.AFlow) return;\n\n  var G = global.AFlow.G, C = global.AFlow.C;\n  var M = B.M;\n\n  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }\n  function f(v, n) { return (v == null || !isFinite(v)) ? '—' : Number(v).toFixed(n === undefined ? 2 : n); }\n\n  var N = 60, H = 200, x0 = 36, y0 = 150, W = 360, xS = W / N, yS = 180 / 22;\n\n  function linePath(arr, x0, y0, color, dash) {\n    var s = '<path d=\"M';\n    for (var i = 0; i < N; i++) {\n      s += (x0 + i * xS).toFixed(1) + ' ' + (y0 + H - arr[i] * yS).toFixed(1);\n      if (i < N - 1) s += ' L';\n    }\n    s += '\" fill=\"none\" stroke=\"' + color + '\" stroke-width=\"' + (dash ? 1.8 : 2) + '\"' + (dash ? ' stroke-dasharray=\"5 3\"' : '') + '/>';\n    return s;\n  }\n\n  function footBox(x, w, y, h, title, lines, tone) {\n    var bg = tone === 'jade' ? C.jadeL : tone === 'clay' ? C.clayL : tone === 'blue' ? C.blueL : '#f4f3ef';\n    var st = tone === 'jade' ? '#b9d8cb' : tone === 'clay' ? '#e6cdb2' : tone === 'blue' ? '#c5d6ea' : C.line;\n    var fg = tone === 'jade' ? C.jadeD : tone === 'clay' ? '#8a4f27' : tone === 'blue' ? '#2b4a72' : C.ink2;\n    var s = G.rect(x, y, w, h, { r: 6, fill: bg, stroke: st });\n    if (title) s += G.txt(x + 11, y + 17, title, { size: 9.6, fill: fg, weight: 700 });\n    for (var i = 0; i < lines.length; i++) {\n      s += G.txt(x + 11, y + (title ? 33 : 17) + i * 13, lines[i], { size: 8.8, fill: fg });\n    }\n    return s;\n  }\n\n  /* ---------- 缓存 ---------- */\n  var cache = { key: '' };\n  function compute() {\n    var L = B.live();\n    var key = [L.weight, L.nIter, L.selPar].join(',');\n    if (cache.key === key) return cache;\n    var seq = M.genDrill(N, 20261131);\n    var pred = M.ropPredict(seq, L.weight);\n    var ev = M.ropEval(seq, pred);\n    var opt = M.bayesOptimize(40, 20261133);\n    var cons = M.conservativeParams();\n    var ropCons = M.ropModel(cons.wob, cons.rpm);\n    var ropOpt = M.ropModel(opt.best.wob, opt.best.rpm);\n    cache = { key: key, L: L, seq: seq, pred: pred, ev: ev, opt: opt, cons: cons, ropCons: ropCons, ropOpt: ropOpt };\n    return cache;\n  }\n\n  /* =========================================================\n     ① 数据接入\n     ========================================================= */\n  function stage1(t) {\n    var c = compute(), seq = c.seq, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 钻时序列', '1—10s 采样', C.clay);\n    s += G.panel(1, '② 井段划分', '地层/工况', C.blue);\n    s += G.panel(2, '③ 参数+钻速', '对应记录', C.jade);\n\n    var x0 = 30, y0 = 130;\n    s += G.axes(x0, y0, 360, 180, { nx: 4, ny: 3 });\n    s += linePath(seq.rop, x0, y0, '#2f7d6b', false);\n    s += G.txt(x0, y0 - 12, '钻速时序（含地层分段趋势）', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(420, 170, 130, 176, '数据特点',\n      ['· 1—10s 采样',\n       '· 单井 10 万—100 万条',\n       '· 钻压/转速/扭矩/排量',\n       '',\n       '缺省/毛刺要清洗，',\n       '否则把毛刺当趋势学。'], 'clay');\n\n    s += G.txt(x0, y0 + 190, '按地层/钻头工况分段，参数与钻速一一对应', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '采样', v: '1—10s' }, { k: '井段', v: '分段优化' }, { k: '规模', v: '10万—100万' }], note: '读入钻时序列，按地层与钻头工况划分井段。钻时序列有缺失与毛刺，不清洗会把毛刺当趋势学进去，预测跟着抖。' };\n  }\n\n  /* =========================================================\n     ② 时序特征\n     ========================================================= */\n  function stage2(t) {\n    var c = compute(), seq = c.seq, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 随钻参数', '钻压/转速', C.blue);\n    s += G.panel(1, '② 滑动窗口', '均值/方差/趋势', C.jade);\n    s += G.panel(2, '③ 时序特征', '喂模型', C.clay);\n\n    var x0 = 30, y0 = 130;\n    /* 三条参数曲线 */\n    var pars = [\n      { name: '钻压', arr: seq.wob, c: '#41699b' },\n      { name: '转速', arr: seq.rpm, c: '#8a4f27' },\n      { name: '扭矩', arr: seq.tor, c: '#6b7a6b' }\n    ];\n    for (var a = 0; a < 3; a++) {\n      var ay = y0 + a * 52;\n      s += G.axes(x0, ay, 300, 42, { nx: 3, ny: 1 });\n      s += linePath(pars[a].arr, x0, ay, pars[a].c, true);\n      s += G.txt(x0 + 310, ay + 20, pars[a].name, { size: 8.5, fill: pars[a].c, weight: 700 });\n    }\n    s += G.txt(x0, y0 - 12, '随钻参数（钻压/转速/扭矩）', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(400, 190, 130, 176, '为什么滑动窗口',\n      ['· 钻速靠过去一段驱动',\n       '· 均值看水平、方差看抖动',\n       '· 趋势看钻头磨损',\n       '',\n       '只看当前时刻会滞后，',\n       '丢掉「钻头正在磨损」',\n       '的趋势信息。'], 'blue');\n\n    s += G.txt(x0, y0 + 170, '构造滑动窗口均值/方差/趋势特征 → 抓钻速时变规律', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '参数', v: '钻压/转速/扭矩' }, { k: '特征', v: '滑动窗口' }, { k: '目标', v: '抓时变' }], note: '从随钻参数构造时序特征（滑动窗口均值/方差/趋势、上一时刻钻速）。只看当前时刻丢掉钻头磨损的趋势信息，预测会滞后。' };\n  }\n\n  /* =========================================================\n     ③ 钻速预测\n     ========================================================= */\n  function stage3(t) {\n    var c = compute(), seq = c.seq, pred = c.pred, ev = c.ev, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 输入层', '参数序列', C.blue);\n    s += G.panel(1, '② 时序层', 'LSTM/Transformer', C.jade);\n    s += G.panel(2, '③ 输出', '钻速', C.clay);\n\n    var x0 = 30, y0 = 130;\n    /* 网络结构 */\n    var layers = [\n      { x: x0, y: y0 + 20, w: 120, h: 120, c: C.blueL, label: '参数序列' },\n      { x: x0 + 140, y: y0 + 40, w: 90, h: 80, c: C.jadeL, label: 'LSTM' },\n      { x: x0 + 250, y: y0 + 40, w: 90, h: 80, c: C.jadeL, label: 'Dense' },\n      { x: x0 + 360, y: y0 + 55, w: 90, h: 50, c: C.clayL, label: '钻速' }\n    ];\n    for (var i = 0; i < layers.length; i++) {\n      var lx = layers[i].x, ly = layers[i].y;\n      s += G.rect(lx, ly, layers[i].w, layers[i].h, { r: 8, fill: layers[i].c, stroke: i === 0 ? '#9fb5cf' : i === 3 ? '#d8a48c' : '#a7c6b8' });\n      s += G.txt(lx + layers[i].w / 2, ly + layers[i].h / 2, layers[i].label, { size: 8.5, fill: C.ink2, anchor: 'middle' });\n      if (i > 0) s += G.line(lx - 12, ly + layers[i].h / 2, lx - 4, ly + layers[i].h / 2, { stroke: '#9ba3a9', sw: 1 });\n    }\n\n    /* 右：拟合 */\n    var rx = x0 + 470, ry = y0;\n    s += G.axes(rx, ry, 130, 150, { nx: 2, ny: 2 });\n    s += '<path d=\"M' + (rx + 10) + ' ' + (ry + 30) + ' C' + (rx + 40) + ' ' + (ry + 60) + ' ' + (rx + 60) + ' ' + (ry + 80) + ' ' + (rx + 110) + ' ' + (ry + 120) + '\" fill=\"none\" stroke=\"#2f7d6b\" stroke-width=\"2\"/>';\n    s += '<path d=\"M' + (rx + 10) + ' ' + (ry + 36) + ' C' + (rx + 40) + ' ' + (ry + 64) + ' ' + (rx + 60) + ' ' + (ry + 76) + ' ' + (rx + 110) + ' ' + (ry + 122) + '\" fill=\"none\" stroke=\"#b26a39\" stroke-width=\"1.6\" stroke-dasharray=\"4 3\"/>';\n    s += G.txt(rx + 10, ry - 8, 'RMSE ' + f(ev.rmse, 2) + ' m/h', { size: 8.5, fill: C.ink3 });\n\n    return { svg: s, stats: [{ k: 'RMSE', v: f(ev.rmse, 2) + ' m/h' }, { k: '相关系数', v: f(ev.corr, 2) }], note: '用时序回归（LSTM/Transformer）从随钻参数序列预测钻速，替代经验拍脑袋，为优化提供「钻速=函数(参数)」。只拟合训练井段，换地层/换钻头后分布漂移，预测会失准。' };\n  }\n\n  /* =========================================================\n     ④ 贝叶斯优化\n     ========================================================= */\n  function stage4(t) {\n    var c = compute(), opt = c.opt, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 代理模型', '钻速=函数(参数)', C.jade);\n    s += G.panel(1, '② 贝叶斯采样', '参数空间', C.blue);\n    s += G.panel(2, '③ 最优参数', '钻速↑ 风险控', C.clay);\n\n    var x0 = 30, y0 = 130;\n    /* 参数空间热力图 + 优化轨迹 */\n    var Wc = 44, Hc = 34, cell = 6;\n    var wobMin = 5, wobMax = 14, rpmMin = 35, rpmMax = 75;\n    for (var r = 0; r < Hc; r++) {\n      for (var c2 = 0; c2 < Wc; c2++) {\n        var wob = wobMin + (c2 / (Wc - 1)) * 9;\n        var rpm = rpmMin + (r / (Hc - 1)) * 40;\n        var m = M.ropModel(wob, rpm);\n        var risk = m.risk;\n        var col;\n        if (risk > 4) col = 'rgb(180,96,86)';\n        else col = 'rgb(' + Math.round(230 - m.rop / 22 * 130) + ',' + Math.round(90 + m.rop / 22 * 150) + ',' + Math.round(230 - m.rop / 22 * 120) + ')';\n        s += G.rect(x0 + c2 * cell, y0 + r * cell, cell, cell, { fill: col, op: 1 });\n      }\n    }\n    for (var i = 0; i < opt.trace.length; i++) {\n      var t = opt.trace[i];\n      var cx = x0 + ((t.wob - wobMin) / 9) * (Wc * cell);\n      var cy = y0 + ((t.rpm - rpmMin) / 40) * (Hc * cell);\n      s += G.circle(cx, cy, 2, { fill: 'none', stroke: '#24333a', sw: 1 });\n    }\n    var b = opt.best;\n    var bx = x0 + ((b.wob - wobMin) / 9) * (Wc * cell);\n    var by = y0 + ((b.rpm - rpmMin) / 40) * (Hc * cell);\n    s += G.circle(bx, by, 4, { fill: '#24333a', stroke: '#fff', sw: 1.5 });\n    s += G.txt(bx, by - 6, '最优', { size: 8, fill: '#24333a', anchor: 'middle', weight: 700 });\n    s += G.txt(x0, y0 - 12, '参数空间热力图 + 贝叶斯优化轨迹', { size: 9.5, fill: C.ink2, weight: 700 });\n    s += G.txt(x0, y0 + Hc * cell + 12, '红区 = 高风险（伤钻头）· 黑点 = 优化轨迹', { size: 8.5, fill: C.ink3 });\n\n    return { svg: s, stats: [{ k: '最优钻压', v: f(b.wob, 1) }, { k: '最优转速', v: f(b.rpm, 0) }, { k: '钻速', v: f(b.rop, 1) + ' m/h' }], note: '用贝叶斯优化/代理模型在参数空间找最优钻压与转速，兼顾效率与风险。只优化钻速不考虑风险，会把参数推到伤钻头的高风险区。' };\n  }\n\n  /* =========================================================\n     ⑤ 保守 vs 最优\n     ========================================================= */\n  function stage5(t) {\n    var c = compute(), ropCons = c.ropCons, ropOpt = c.ropOpt, cons = c.cons, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 保守参数', '宁慢勿坏', C.blue);\n    s += G.panel(1, '② 最优参数', '预测最优', C.jade);\n    s += G.panel(2, '③ 提升+风险', '可控', C.clay);\n\n    var x0 = 40, y0 = 60, cw = 120, ch = 150;\n    var maxRop = Math.max(ropCons.rop, ropOpt.rop, 1);\n    var hCons = ropCons.rop / maxRop * ch;\n    var hOpt = ropOpt.rop / maxRop * ch;\n    s += G.axes(x0, y0, 340, ch + 20, { nx: 0, ny: 3 });\n    s += G.rect(x0 + 20, y0 + ch - hCons, 100, hCons, { fill: '#41699b' });\n    s += G.txt(x0 + 70, y0 + ch - hCons - 6, f(ropCons.rop, 1), { size: 10, fill: '#41699b', anchor: 'middle', weight: 700 });\n    s += G.txt(x0 + 70, y0 + ch + 16, '保守参数', { size: 9, fill: '#41699b', anchor: 'middle' });\n    s += G.rect(x0 + 190, y0 + ch - hOpt, 100, hOpt, { fill: '#2f7d6b' });\n    s += G.txt(x0 + 240, y0 + ch - hOpt - 6, f(ropOpt.rop, 1), { size: 10, fill: '#2f7d6b', anchor: 'middle', weight: 700 });\n    s += G.txt(x0 + 240, y0 + ch + 16, '最优参数', { size: 9, fill: '#2f7d6b', anchor: 'middle' });\n    s += G.txt(x0 + 300, y0 + 20, '+' + Math.round((ropOpt.rop / ropCons.rop - 1) * 100) + '%', { size: 13, fill: C.clayD, weight: 700 });\n\n    s += footBox(430, 160, 60, 150, '风险对比',\n      ['· 保守钻压 ' + f(cons.wob, 1) + '、转速 ' + f(cons.rpm, 0),\n       '· 最优钻压 ' + f(optBestWob(), 1) + '、转速 ' + f(optBestRpm(), 0),\n       '',\n       '提升钻速不能以废',\n       '钻头为代价，要看',\n       '风险段是否可控。'], 'clay');\n\n    return { svg: s, stats: [{ k: '保守钻速', v: f(ropCons.rop, 1) + ' m/h' }, { k: '最优钻速', v: f(ropOpt.rop, 1) + ' m/h' }, { k: '提升', v: '+' + Math.round((ropOpt.rop / ropCons.rop - 1) * 100) + '%' }], note: '对比保守参数与最优参数的钻速与风险。提升只看钻速平均、不盯风险段，某个高风险井段提速可能引发卡钻。' };\n  }\n\n  /* =========================================================\n     ⑥ 部署与回流\n     ========================================================= */\n  function stage6(t) {\n    var c = compute(), ev = c.ev, opt = c.opt, b = opt.best, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 最优参数方案', '按井段给', C.blue);\n    s += G.panel(1, '② 人工确认', '工程师审核', C.clay);\n    s += G.panel(2, '③ 在线更新', '随钻回流', C.jade);\n\n    var x0 = 30, y0 = 130;\n    /* 方案清单 */\n    var rows = [\n      ['一开井段', '钻压 ' + f(b.wob, 1) + ' / 转速 ' + f(b.rpm, 0), 'ok'],\n      ['二开井段', '待在线更新', '复查'],\n      ['三开井段', '按地层重估', '复查'],\n      ['风险井段', '降速保安全', 'ok']\n    ];\n    for (var r = 0; r < rows.length; r++) {\n      var ry = y0 + r * 30;\n      s += G.rect(x0, ry, 360, 24, { r: 4, fill: rows[r][2] === 'ok' ? C.jadeL : C.clayL, stroke: rows[r][2] === 'ok' ? '#b9d8cb' : '#e6cdb2' });\n      s += G.txt(x0 + 12, ry + 16, rows[r][0], { size: 8.8, fill: C.ink2, weight: 700 });\n      s += G.txt(x0 + 110, ry + 16, rows[r][1], { size: 8.8, fill: rows[r][2] === 'ok' ? C.jadeD : '#8a4f27' });\n      s += G.txt(x0 + 320, ry + 16, rows[r][2], { size: 8.8, fill: rows[r][2] === 'ok' ? C.jadeD : '#8a4f27', weight: 700 });\n    }\n    s += G.txt(x0, y0 - 12, '按井段的钻井参数方案清单', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(420, 170, 130, 176, '在线更新的价值',\n      ['· 随钻数据回流模型',\n       '· 强化学习随钻更新策略',\n       '· 新井段更快适应',\n       '· 地层变参数跟着变',\n       '',\n       '预测 RMSE ' + f(ev.rmse, 2),\n       '无在线更新 → 地层一变',\n       '最优参数立刻过期。'], 'jade');\n\n    s += G.txt(x0, y0 + 140, '产出：按井段最优参数 + 风险标注 → 钻井方案 + 随钻回流', { size: 9, fill: C.ink3 });\n    return { svg: s, stats: [{ k: '预测 RMSE', v: f(ev.rmse, 2) + ' m/h' }, { k: '产出', v: '最优参数方案' }], note: '工程师按最优参数制定钻井方案；随钻数据反馈回模型，强化学习随钻更新策略。方案上线后没有在线更新，地层一变最优参数立刻过期。' };\n  }\n\n  function optBestWob() { return compute().opt.best.wob; }\n  function optBestRpm() { return compute().opt.best.rpm; }\n\n  global.RemoteFlow = { stage1: stage1, stage2: stage2, stage3: stage3, stage4: stage4, stage5: stage5, stage6: stage6 };\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/index.html","mime":"text/html","data":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>示范：钻速预测与参数优化<\/title>\n<link rel=\"stylesheet\" href=\"demo.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aflow.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aiq.css?v=20261105a\">\n<style>\n#ctlDrawer{position:fixed;right:0;top:70px;width:268px;max-height:calc(100vh - 120px);overflow-y:auto;background:#fff;border:1px solid #e9e4d8;border-radius:10px;box-shadow:0 6px 24px -8px rgba(0,0,0,.15);z-index:90;transform:translateX(-100%);opacity:0;pointer-events:none;transition:transform .3s ease,opacity .3s ease}\n#ctlDrawer.open{transform:translateX(0);opacity:1;pointer-events:auto}\n@media (max-width:760px){#ctlDrawer{width:calc(100vw - 20px);right:10px;top:auto;bottom:10px;max-height:45vh}}\n<\/style>\n<\/head>\n<body>\n\n<header class=\"hd\">\n  <span class=\"kicker\">CASE DEMO · 钻井工程 / 钻速预测与参数优化<\/span>\n  <h1>从「经验试钻 · 保守压速」到「时序预测 + 贝叶斯优化」<\/h1>\n  <p class=\"sub\">三个实验：Q1 看懂钻速预测、Q2 贝叶斯优化、Q3 保守 vs 最优参数。<\/p>\n<\/header>\n\n<!-- ================= 算法解剖 · 钻速优化全流程 ================= -->\n<section class=\"sec\" id=\"sec0\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">深入 · 想逐帧看就往下<\/span>\n    <p class=\"qa-a\">不是「随钻参数 → 黑盒 → 最优钻速」，而是<b>逐段展开<\/b>：数据接入 → 时序特征 → 钻速预测 → 贝叶斯优化 → 保守对比 → 部署回流，每一步都能看见中间量<\/p>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">可选深入 · 对应流程 STEP 3—5<\/span>\n    <h2>把「参数 → 最优钻速」一步步拆开看<\/h2>\n    <p class=\"leadline\">下面这段动画跑的是<b>真代码<\/b>（与实验 1—3 同一份模型）。自动播放，也可点阶段名跳步、拖速度。改回归权重、优化迭代数，这里的每一步都会同步重算。<\/p>\n  <\/div>\n  <div id=\"flowMount\"><\/div>\n  <details class=\"more\">\n    <summary>这段动画与后面三个实验是什么关系<\/summary>\n    <div class=\"more-body\">\n      <p>实验 1—3 给出的是<b>结果<\/b>（钻速预测、优化轨迹、参数对比）；这段动画给出的是<b>过程<\/b>——同一份 <code>demo.js<\/code> 里的 <code>ropPredict / bayesOptimize / ropModel<\/code> 被拆成 6 个阶段依次放慢演给你看。<\/p>\n      <p>刻意做的两处细节：<b>①<\/b> 第 4 步用参数空间热力图 + 优化轨迹，看得见贝叶斯优化在钻压×转速空间里怎么采样收敛；<b>②<\/b> 第 5 步把保守与最优参数的钻速柱并排放，看得见 20—30% 的提升从哪来。<\/p>\n    <\/div>\n  <\/details>\n<\/section>\n\n<!-- ================= 实验 1 · 钻速时序预测 ================= -->\n<section class=\"sec\" id=\"sec1\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q1 · 为什么需要智能算法<\/span>\n    <p class=\"qa-a\">经验试钻靠拍脑袋；时序回归从随钻参数预测钻速<\/p>\n    <button class=\"qa-go\">开始实验 1<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 1 · 对应流程 STEP 3<\/span>\n    <h2>钻速时序预测：随钻参数 → 钻速<\/h2>\n    <p class=\"leadline\">拖回归权重看预测贴近真值的程度；切不同随钻参数看它随时间的变化——这些参数一起驱动钻速。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"predCtl\">\n    <div class=\"sl\">\n      <label>回归权重<output id=\"outWeight\">0.70<\/output><\/label>\n      <input type=\"range\" id=\"inWeight\" min=\"0\" max=\"1.2\" step=\"0.05\" value=\"0.7\">\n    <\/div>\n    <div class=\"sl\">\n      <label>显示参数<output id=\"outPar\">钻压<\/output><\/label>\n      <input type=\"range\" id=\"inPar\" min=\"0\" max=\"3\" step=\"1\" value=\"0\">\n    <\/div>\n  <\/div>\n  <svg id=\"ropChart\" viewBox=\"0 0 470 280\" role=\"img\" aria-label=\"钻速时序预测\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">预测 RMSE<\/span><b id=\"roRmse\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">相关系数<\/span><b id=\"roCorr\">—<\/b><\/div>\n  <\/div>\n  <svg id=\"parChart\" viewBox=\"0 0 400 120\" role=\"img\" aria-label=\"随钻参数变化\"><\/svg>\n  <p class=\"tip\" id=\"predTip\">绿色 = 真实钻速，红色虚线 = 预测。钻速由钻压/转速/扭矩/排量共同驱动，且随时间漂移（地层变化、钻头磨损）。时序回归比只看当前时刻的普通回归更能抓住趋势。<\/p>\n<\/section>\n\n<!-- ================= 实验 2 · 贝叶斯优化 ================= -->\n<section class=\"sec\" id=\"sec2\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q2 · 智能算法是什么<\/span>\n    <p class=\"qa-a\"><b>贝叶斯优化<\/b>：用代理模型在参数空间找最优钻压与转速<span class=\"qa-algo\">贝叶斯优化 · 代理模型<\/span><\/p>\n    <button class=\"qa-go\">开始实验 2<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 2 · 对应流程 STEP 4<\/span>\n    <h2>贝叶斯优化：在参数空间找最优，避开高风险区<\/h2>\n    <p class=\"leadline\">拖优化迭代数，看贝叶斯优化在钻压×转速空间采样收敛到最优点，红区是伤钻头的高风险区。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"optCtl\">\n    <div class=\"sl\">\n      <label>优化迭代数<output id=\"outIter\">24<\/output><\/label>\n      <input type=\"range\" id=\"inIter\" min=\"4\" max=\"60\" step=\"2\" value=\"24\">\n    <\/div>\n  <\/div>\n  <svg id=\"optChart\" viewBox=\"0 0 300 220\" role=\"img\" aria-label=\"贝叶斯优化参数空间\"><\/svg>\n  <div class=\"rrow ro3\">\n    <div class=\"ro\"><span class=\"k\">最优参数<\/span><b id=\"roBest\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">风险<\/span><b id=\"roRisk\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">迭代<\/span><b id=\"roIter\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"optTip\">热力图颜色越深 = 钻速越高；红色区域 = 钻压过大或转速过高、伤钻头的高风险区。贝叶斯优化用代理模型在钻压×转速空间采样，逐步逼近「钻速高且风险低」的最优点（黑点）。<\/p>\n<\/section>\n\n<!-- ================= 实验 3 · 保守 vs 最优参数 ================= -->\n<section class=\"sec\" id=\"sec3\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q3 · 它怎么工作<\/span>\n    <p class=\"qa-a\">预测钻速 → <b>贝叶斯优化<\/b>给最优参数 → 替代保守参数的 20—30% 钻速损失<\/p>\n    <button class=\"qa-go\">开始实验 3<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 3 · 对应流程 STEP 5<\/span>\n    <h2>保守 vs 最优参数：钻速提升与风险可控<\/h2>\n    <p class=\"leadline\">对比保守参数（宁慢勿坏）与贝叶斯优化给的最优参数，看钻速提升与风险是否可控。<\/p>\n  <\/div>\n  <svg id=\"cmpChart\" viewBox=\"0 0 440 340\" role=\"img\" aria-label=\"保守与最优参数对比\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">钻速提升<\/span><b id=\"roLift\" class=\"good\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">风险对比<\/span><b id=\"roRiskCmp\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"cmpTip\">保守参数把钻速压低约 25%，最优参数在避开高风险区的同时把钻速提回来。提升钻速不能以废钻头为代价——风险段（红区附近）必须控制，最终看钻头寿命与建井周期。<\/p>\n<\/section>\n\n<footer>\n  <div class=\"map\">\n    <div><b>实验 1 → STEP 3<\/b><br>钻速时序预测。<\/div>\n    <div><b>实验 2 → STEP 4<\/b><br>贝叶斯优化找最优参数。<\/div>\n    <div><b>实验 3 → STEP 5<\/b><br>保守 vs 最优 + 风险可控。<\/div>\n  <\/div>\n  <p class=\"note\">纯前端教学演示：钻时序列由「地层分段趋势 + 随钻参数」合成，钻速真值已知、仅供对比；时序回归、贝叶斯优化与参数对比均在浏览器实时计算。<\/p>\n<\/footer>\n\n<script src=\"demo.js\"><\/script>\n<script src=\"aflow.js\"><\/script>\n<script src=\"flow.js\"><\/script>\n<script>\n/* 算法解剖：把 6 个阶段挂到 AFlow 引擎上 */\n(function () {\n  if (!window.AFlow || !window.RemoteFlow) return;\n  var F = window.RemoteFlow;\n  window.RemoteFlowApi = window.AFlow.create({\n    mount: document.getElementById('flowMount'),\n    title: '算法解剖',\n    subtitle: '自动播放：随钻参数怎么一步步变成最优钻速',\n    stages: [\n      { name: '数据接入', tag: '井段划分', dur: 4000, draw: function (t, g) { return F.stage1(t); } },\n      { name: '时序特征', tag: '滑动窗口', dur: 4200, draw: function (t, g) { return F.stage2(t); } },\n      { name: '钻速预测', tag: '时序回归', dur: 4800, draw: function (t, g) { return F.stage3(t); } },\n      { name: '贝叶斯优化', tag: '参数空间', dur: 5000, draw: function (t, g) { return F.stage4(t); } },\n      { name: '保守vs最优', tag: '钻速+风险', dur: 4400, draw: function (t, g) { return F.stage5(t); } },\n      { name: '部署与回流', tag: '在线更新', dur: 4400, draw: function (t, g) { return F.stage6(t); } }\n    ]\n  });\n})();\n<\/script>\n<script src=\"aiq.js?v=20261105a\"><\/script>\n<\/body>\n<\/html>\n"}];
  var CFG = {"mode":"auto","html":"demo/index.html","js":"demo/demo.js","label":"可运行示范","intro":"用合成的钻时序列演示钻速时序预测、贝叶斯优化与保守参数对比。","height":600};
  var META = {"id":"d1-rop-optimize","sceneId":"d1","title":"钻速预测与参数优化：贝叶斯优化替代保守参数"};
  var handle = null;
  var DEF = {"id":"d1-rop-optimize","sceneId":"d1","title":"钻速预测与参数优化：贝叶斯优化替代保守参数","methods":["ts","opt"],"version":"1.0.0","updated":"2026-11-05","status":"ready","tabs":{"background":{"label":"专业背景","judge":[{"label":"数据形态","value":"钻时序列","desc":"1—10s 采样，单井 10 万—100 万条"},{"label":"标注成本","value":"低","desc":"钻速、扭矩可直接测得"},{"label":"可见收益","value":"钻速提升","desc":"保守参数压低 20—30%"},{"label":"难度","value":"高","desc":"时序回归 + 参数优化"}],"lede":"钻速（ROP，Rate of Penetration）是钻井效率的核心指标。传统靠经验试钻：参数（钻压、转速）调保守一点防钻具损坏，却常把钻速压低 20—30%。智能方法用时序回归预测钻速，再结合贝叶斯优化/强化学习找最优参数组合。","sections":[{"no":1,"en":"PROBLEM","title":"当前做法与问题","html":"<p>钻井工程师靠经验试钻：在井场盯着<b>钻压、转速、扭矩、排量<\/b>这些随钻参数，拍脑袋调一个<b>保守参数<\/b>组合，宁慢勿坏。结果就是——钻速被压低，但真正的风险（钻头磨损、卡钻）并不一定被防住。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>钻速被压低 20—30%<\/b>——保守参数宁慢勿坏，拖慢建井周期<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>经验试钻<\/b>——参数怎么组合最优，依赖个人经验，难以复用<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>不敢冒险<\/b>——怕钻头损坏、卡钻，宁可牺牲效率<\/span><\/div><\/div><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"传统试钻的保守参数问题\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">传统试钻：保守参数压低钻速 20—30%<\/text><rect x=\"20\" y=\"36\" width=\"280\" height=\"176\" rx=\"8\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"160\" y=\"56\" text-anchor=\"middle\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">经验试钻流程<\/text><rect x=\"36\" y=\"70\" width=\"120\" height=\"30\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"96\" y=\"90\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#2b4a72\">盯随钻参数<\/text><rect x=\"180\" y=\"70\" width=\"100\" height=\"30\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"230\" y=\"90\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a4f27\">经验试钻<\/text><rect x=\"36\" y=\"112\" width=\"120\" height=\"30\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"96\" y=\"132\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#22604f\">调保守参数<\/text><rect x=\"180\" y=\"112\" width=\"100\" height=\"30\" rx=\"5\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"230\" y=\"132\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a4f27\">宁慢勿坏<\/text><text x=\"160\" y=\"180\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#b26a39\" font-weight=\"700\">钻速被压低 20—30%<\/text><text x=\"160\" y=\"198\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#79828a\">但风险不一定被防住<\/text><rect x=\"316\" y=\"36\" width=\"284\" height=\"176\" rx=\"8\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"458\" y=\"56\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">三个痛点<\/text><text x=\"332\" y=\"82\" font-size=\"9.5\" fill=\"#4d565b\">· 钻速压低，建井周期拖慢<\/text><text x=\"332\" y=\"104\" font-size=\"9.5\" fill=\"#4d565b\">· 参数组合依赖个人经验<\/text><text x=\"332\" y=\"126\" font-size=\"9.5\" fill=\"#4d565b\">· 不敢冒险，牺牲效率<\/text><rect x=\"332\" y=\"150\" width=\"252\" height=\"46\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"344\" y=\"170\" font-size=\"8.5\" fill=\"#79828a\">风险（钻头磨损、卡钻）<\/text><text x=\"344\" y=\"186\" font-size=\"8.5\" fill=\"#b26a39\" font-weight=\"700\">保守不一定防住风险<\/text><\/svg><\/div>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>把「经验试钻」换成「<b>预测 + 优化<\/b>」：先用<b>时序回归<\/b>从随钻参数预测钻速，再用<b>贝叶斯优化 / 强化学习<\/b>找最优参数组合，一次算出该井段的最优钻压与转速。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>钻速时序预测<\/b>——从钻压/转速/扭矩预测当前钻速，替代拍脑袋<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>贝叶斯优化<\/b>——用代理模型在参数空间找最优，兼顾效率与风险<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>在线学习<\/b>——强化学习随钻更新策略，新井段更快适应<\/span><\/div><\/div><p>落地形态：参数从「保守压钻速」改成「<b>按预测最优给<\/b>」，钻速提升、风险可控。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"预测+优化流程\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">预测 + 优化：时序回归 + 贝叶斯优化<\/text><rect x=\"20\" y=\"40\" width=\"120\" height=\"120\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"80\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#242b2e\" font-weight=\"600\">随钻参数<\/text><path d=\"M36 78 C60 62 90 76 116 68\" fill=\"none\" stroke=\"#7a8a9a\" stroke-width=\"2.6\"/><text x=\"80\" y=\"130\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">钻压/转速/扭矩/排量<\/text><path d=\"M144 100 L168 100\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"172\" y=\"40\" width=\"130\" height=\"120\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"237\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">时序回归<\/text><text x=\"237\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">预测钻速<\/text><text x=\"237\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">替代拍脑袋<\/text><path d=\"M306 100 L330 100\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"334\" y=\"40\" width=\"130\" height=\"120\" rx=\"6\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"399\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#2b4a72\" font-weight=\"600\">贝叶斯优化<\/text><text x=\"399\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">找最优参数<\/text><text x=\"399\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">钻压+转速<\/text><path d=\"M468 100 L492 100\" stroke=\"#2b4a72\" stroke-width=\"1.6\"/><rect x=\"496\" y=\"40\" width=\"104\" height=\"120\" rx=\"6\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"548\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">最优钻速<\/text><text x=\"548\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">效率+风险<\/text><text x=\"548\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">兼顾<\/text><path d=\"M548 160 C548 188 320 192 320 210\" fill=\"none\" stroke=\"#9ba3a9\" stroke-width=\"1.4\" stroke-dasharray=\"4 3\"/><text x=\"430\" y=\"186\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">在线学习（强化学习随钻更新）<\/text><text x=\"310\" y=\"228\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">参数从「保守压钻速」改成「按预测最优给」→ 钻速提升、风险可控<\/text><\/svg><\/div>"},{"no":3,"en":"DATA","title":"需要准备什么","html":"<p><b>钻时序列<\/b>：1—10s 采样，单井 10 万—100 万条，含钻压、转速、扭矩、排量、钻速；<b>井段划分<\/b>：按地层/钻头工况分段；<b>风险约束<\/b>：钻头磨损、卡钻的工况标注。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 220\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"钻速数据准备\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">钻速优化需要的数据<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#41699b\"/><text x=\"32\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">钻时序列<\/text><text x=\"32\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">1—10s 采样<\/text><text x=\"32\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">单井 10 万—100 万条<\/text><rect x=\"318\" y=\"34\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#2f7d6b\"/><text x=\"330\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">随钻参数<\/text><text x=\"330\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">钻压/转速/扭矩/排量<\/text><text x=\"330\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">对应钻速<\/text><rect x=\"20\" y=\"106\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#b26a39\"/><text x=\"32\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">井段划分<\/text><text x=\"32\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">按地层/钻头工况分段<\/text><text x=\"32\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">分段优化参数<\/text><rect x=\"318\" y=\"106\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#79828a\"/><text x=\"330\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">风险约束<\/text><text x=\"330\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">钻头磨损/卡钻工况<\/text><text x=\"330\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">优化时排除高风险<\/text><rect x=\"20\" y=\"184\" width=\"582\" height=\"26\" rx=\"6\" fill=\"#f8ecdf\"/><text x=\"32\" y=\"202\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">训练策略：时序回归（多参数→钻速）+ 贝叶斯优化（找最优参数）+ 风险约束<\/text><\/svg><\/div>"},{"no":4,"en":"DIFFICULTY","title":"难度与参考方向","html":"<p>三个最容易翻车的点：<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>时序非平稳<\/b>——地层变化、钻头磨损让钻速随时间漂移，简单回归失效<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>优化与风险耦合<\/b>——最高钻速的参数可能伤钻头，只优化钻速会出错<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>数据规模大<\/b>——单井 10 万—100 万条，实时预测+优化要控制延迟<\/span><\/div><\/div><p>改进路线按成本从低到高：先用<b>时序回归<\/b>（LSTM/Transformer）建钻速预测基线；再加<b>贝叶斯优化 / 代理模型<\/b>找最优参数、避开高风险区；最后用<b>强化学习<\/b>随钻更新策略，让新井段更快适应。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"钻速优化难点与对策\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">难点排序 + 成本从低到高的改进路线<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"52\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">① 时序非平稳<\/text><text x=\"32\" y=\"68\" font-size=\"8.5\" fill=\"#6b4a35\">地层/磨损让钻速漂移<\/text><path d=\"M310 57 L356 57\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"34\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"52\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">LSTM / Transformer<\/text><text x=\"372\" y=\"68\" font-size=\"8.5\" fill=\"#4d565b\">长时序建模<\/text><rect x=\"20\" y=\"86\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"104\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">② 优化与风险耦合<\/text><text x=\"32\" y=\"120\" font-size=\"8.5\" fill=\"#6b4a35\">最高钻速伤钻头<\/text><path d=\"M310 109 L356 109\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"86\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"104\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">贝叶斯/代理模型<\/text><text x=\"372\" y=\"120\" font-size=\"8.5\" fill=\"#4d565b\">避开高风险区<\/text><rect x=\"20\" y=\"138\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"156\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">③ 数据规模大<\/text><text x=\"32\" y=\"172\" font-size=\"8.5\" fill=\"#6b4a35\">实时预测优化延迟<\/text><path d=\"M310 161 L356 161\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"138\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"156\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">强化学习随钻更新<\/text><text x=\"372\" y=\"172\" font-size=\"8.5\" fill=\"#4d565b\">新井段更快适应<\/text><rect x=\"20\" y=\"192\" width=\"582\" height=\"16\" rx=\"8\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"310\" y=\"204\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#41699b\">时序回归基线 → 贝叶斯优化 + 风险约束 → 强化学习在线更新<\/text><\/svg><\/div>"}]},"workflow":{"label":"案例流程","title":"案例：一口井的钻速预测与参数优化改造","lead":["某井一开井段此前用保守参数试钻，钻速被压低约 25%。目标：用时序回归预测钻速 + 贝叶斯优化找最优钻压与转速，把钻速提上去且不伤钻头。","注意第 3、4、5 步：钻速时序预测、贝叶斯优化、保守参数对比是智能化价值的三个落点，示范页三屏一一对应。"],"stats":[["井段","一开某井段"],["钻时采样","1—10s"],["序列规模","单井 10 万—100 万条"],["保守压速","约 25%"],["目标","预测+优化钻速"],["风险","钻头磨损/卡钻"]],"steps":[{"name":"钻时数据接入与清洗","role":"数据","do":"读入钻时序列（钻压/转速/扭矩/排量/钻速），按地层与钻头工况划分井段。示范页屏 1 顶部可切换不同随钻参数看对钻速的影响。","effect":"一份按井段切分的钻时序列，作为预测与优化的输入。","trap":"钻时序列有缺失与毛刺，不清洗直接把毛刺当趋势学进去，预测会跟着抖。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">数据接入：钻时序列 → 井段划分<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">钻时序列<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">1—10s / 10万—100万条<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"170\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"291\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">按地层/工况划分<\/text><text x=\"291\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">分段优化<\/text><path d=\"M380 72 L404 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"408\" y=\"42\" width=\"186\" height=\"60\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"501\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">清洗缺省/毛刺<\/text><text x=\"501\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">避免毛刺当趋势<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：缺省/毛刺不清洗 → 把毛刺当趋势学 → 预测跟着抖<\/text><\/svg>"},{"name":"时序特征工程","role":"特征","do":"从随钻参数构造时序特征：滑动窗口均值/方差、趋势、上一时刻钻速等。示范页屏 1 顶部切参数看不同特征对钻速预测的贡献。","effect":"一组能抓住钻速随时间变化的时序特征，喂给预测模型。","trap":"特征只看当前时刻，丢掉了「钻头正在磨损」的趋势信息，预测会滞后。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">特征工程：随钻参数 → 时序特征<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">随钻参数<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">钻压/转速/扭矩<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"180\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"296\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">滑动窗口特征<\/text><text x=\"296\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">均值/方差/趋势/上时刻<\/text><path d=\"M390 72 L414 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"418\" y=\"42\" width=\"176\" height=\"60\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"506\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">喂预测模型<\/text><text x=\"506\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">抓住时变趋势<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：只看当前时刻 → 丢「钻头磨损」趋势 → 预测滞后<\/text><\/svg>"},{"name":"钻速时序预测","role":"算法核心","do":"用 LSTM/Transformer 从随钻参数序列预测钻速，替代经验拍脑袋。示范页屏 1 在浏览器里实时跑预测并看 RMSE。","effect":"一个能按随钻参数预测钻速的时序模型，为优化提供「钻速=函数(参数)」。","trap":"模型只拟合训练井段，换地层/换钻头后分布漂移，预测立刻失准。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">钻速预测：随钻参数 → 钻速（时序回归）<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">随钻参数序列<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">窗口输入<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"281\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">LSTM/Transformer<\/text><text x=\"281\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">时序回归<\/text><path d=\"M360 72 L384 72\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"206\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"491\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">钻速预测<\/text><text x=\"491\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">优化用代理<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：只拟合训练井段 → 换地层/钻头分布漂移 → 预测失准<\/text><\/svg>"},{"name":"贝叶斯优化找最优参数","role":"算法核心","do":"用贝叶斯优化 / 代理模型在参数空间（钻压、转速）找最优组合，兼顾钻速与风险。示范页屏 2 实时展示优化过程与最优参数。","effect":"一个可给出「最优钻压+转速」的优化器，比经验试钻快且准。","trap":"只优化钻速不考虑风险，把参数推到伤钻头的高风险区，省了时间废了钻头。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">贝叶斯优化：参数空间 → 最优钻压+转速<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">代理模型<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">钻速=函数(参数)<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"180\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"296\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">贝叶斯采样<\/text><text x=\"296\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">钻压×转速空间<\/text><path d=\"M390 72 L414 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"418\" y=\"42\" width=\"176\" height=\"60\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"506\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">最优参数<\/text><text x=\"506\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">钻速↑ 风险控<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：只优化钻速 → 参数推到伤钻头区 → 省时间废钻头<\/text><\/svg>"},{"name":"保守参数 vs 最优参数","role":"工程环节","do":"对比保守参数（宁慢勿坏）与最优参数的钻速与风险，量化提升。示范页屏 3 实时对比两种参数下的钻速差异。","effect":"看得见的钻速提升（20—30% 的回补）与风险是否可控。","trap":"提升只看钻速平均，不盯风险段——某个高风险井段提速可能引发卡钻。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">对比：保守参数 vs 最优参数<\/text><rect x=\"24\" y=\"42\" width=\"180\" height=\"70\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"114\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">保守参数<\/text><text x=\"114\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">宁慢勿坏 · 钻速压低 25%<\/text><text x=\"114\" y=\"96\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">风险：不一定防住<\/text><rect x=\"416\" y=\"42\" width=\"180\" height=\"70\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"506\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">最优参数<\/text><text x=\"506\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">钻速提升 20—30%<\/text><text x=\"506\" y=\"96\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">风险：按约束控制<\/text><text x=\"310\" y=\"90\" text-anchor=\"middle\" font-size=\"16\" fill=\"#b26a39\" font-weight=\"700\">▲ 25%<\/text><text x=\"24\" y=\"132\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：只看平均提升 → 不盯风险段 → 某个井段提速引发卡钻<\/text><\/svg>"},{"name":"钻井方案部署与在线更新","role":"人工确认","do":"工程师按最优参数制定钻井方案；随钻数据反馈回模型，强化学习随钻更新策略。示范页屏 3 展示按井段分层的方案清单。","effect":"参数按预测最优给，钻速提升、风险可控，新井段适应更快。","trap":"方案上线后没有在线更新，地层一变最优参数立刻过期。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">部署：最优参数 → 方案 + 随钻回流<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">最优参数方案<\/text><text x=\"104\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">按井段给参数<\/text><path d=\"M188 68 L210 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"294\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">人工确认<\/text><text x=\"294\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">工程师审核<\/text><path d=\"M378 68 L400 68\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"499\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">随钻回流 + 在线更新<\/text><text x=\"499\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">强化学习自适应<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：无在线更新 → 地层一变最优参数立刻过期<\/text><\/svg>"}],"metrics":{"title":"怎么算「钻速优化对了」","html":"<p>钻速优化用 <b>钻速提升<\/b>（最优 vs 保守参数的钻速差）与 <b>风险可控<\/b>（是否进入高风险参数区）双重验收；<b>钻头寿命<\/b>是最终金标准——提升钻速不能以废钻头为代价。<\/p><p>最终还要看 <b>建井周期<\/b>：钻速提升能否转化为更短的建井周期，而非仅在钻速指标上好看、风险段却失控。<\/p><p style=\"margin-top:16px\"><svg viewBox='0 0 620 200' xmlns='http://www.w3.org/2000/svg' role='img' aria-label='钻速优化效果对比' style='width:100%;height:auto;display:block'><text x='14' y='20' font-size='10' fill='#4d565b' font-weight='600'>钻速优化验收：钻速提升 × 风险可控<\/text><rect x='14' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='159' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>钻速提升<\/text><rect x='40' y='66' width='80' height='52' fill='#d9b78e'/><text x='80' y='96' text-anchor='middle' font-size='10' fill='#4d565b' font-weight='700'>12 m/h<\/text><text x='80' y='112' text-anchor='middle' font-size='8' fill='#8a6b52'>保守参数<\/text><rect x='180' y='66' width='80' height='52' fill='#2f7d6b'/><text x='220' y='96' text-anchor='middle' font-size='10' fill='#fff' font-weight='700'>15 m/h<\/text><text x='220' y='112' text-anchor='middle' font-size='8' fill='#b9d8cb'>最优参数 +25%<\/text><text x='159' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>钻速提升 +25%<\/text><rect x='316' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='461' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>风险可控（钻头）<\/text><rect x='340' y='66' width='120' height='52' fill='#e7eef9' stroke='#41699b'/><text x='400' y='92' text-anchor='middle' font-size='9' fill='#2b4a72' font-weight='700'>避开高风险区<\/text><text x='400' y='108' text-anchor='middle' font-size='8' fill='#79828a'>参数约束<\/text><rect x='470' y='66' width='120' height='52' fill='#e6f1ec' stroke='#2f7d6b'/><text x='530' y='92' text-anchor='middle' font-size='9' fill='#22604f' font-weight='700'>钻头寿命不降<\/text><text x='530' y='108' text-anchor='middle' font-size='8' fill='#79828a'>建井周期更短<\/text><text x='461' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>最终金标准：钻头寿命 + 建井周期<\/text><text x='310' y='188' text-anchor='middle' font-size='8' fill='#9ba3a9'>验收 = 钻速提升 × 风险可控 × 钻头寿命<\/text><\/svg><\/p>"},"fails":[{"name":"时序非平稳","why":"地层变化、钻头磨损让钻速随时间漂移，简单回归只看当前时刻会滞后，需长时序建模。"},{"name":"优化与风险耦合","why":"最高钻速的参数可能伤钻头，只优化钻速会推到高风险区，必须带风险约束。"},{"name":"数据规模大","why":"单井 10 万—100 万条，实时预测+优化要控制延迟，需代理模型。"},{"name":"模型迁移失效","why":"只拟合训练井段，换地层/换钻头后分布漂移，预测立刻失准。"}]}}};
  DEF.tabs.demo = {
    label: "可运行示范",
    intro: "用合成的钻时序列演示钻速时序预测、贝叶斯优化与保守参数对比。",
    mode: "page",
    mount: function (root, ctx) {
      handle = window.CaseDemoHost.create(root, { files: FILES, demo: CFG, meta: META }, ctx);
    },
    unmount: function () {
      if (handle) { try { handle.destroy(); } catch (e) { } handle = null; }
    }
  };
  window.Cases.register(DEF);
})();
